import { useState, useEffect, useMemo } from 'react'
import { Users, ChevronDown, ChevronRight, Cpu, Paintbrush, Search, BarChart3, Shield } from 'lucide-react'
import { getOrgChart } from '../lib/api'
import type { OrgChartData, OrgChartNode } from '../lib/api'

const TIER_ICONS: Record<string, typeof Cpu> = {
  leadership: Shield,
  engineer: Cpu,
  analyst: BarChart3,
  creative: Paintbrush,
}

const MODEL_BADGES: Record<string, { label: string; className: string }> = {
  opus: { label: 'Opus', className: 'bg-purple-500/20 text-purple-400 border-purple-500/30' },
  sonnet: { label: 'Sonnet', className: 'bg-blue-500/20 text-blue-400 border-blue-500/30' },
}

function AgentCard({ node, children, isExpanded, onToggle, depth = 0 }: {
  node: OrgChartNode
  children: OrgChartNode[]
  isExpanded: boolean
  onToggle: () => void
  depth?: number
}) {
  const [showDetail, setShowDetail] = useState(false)
  const hasChildren = children.length > 0
  const TierIcon = TIER_ICONS[node.tier] || Cpu
  const modelBadge = MODEL_BADGES[node.model] || { label: node.model, className: 'bg-surface-2 text-text-muted' }

  // Extract emoji and clean name
  const emoji = node.name.match(/^(\p{Emoji_Presentation}|\p{Extended_Pictographic})/u)?.[0] || ''
  const cleanName = node.name.replace(/^[\p{Emoji_Presentation}\p{Extended_Pictographic}]\s*[\u200d\ufe0f]*/u, '').replace(/^—\s*/, '').trim()
  const shortName = cleanName.split('—')[0]?.trim() || cleanName

  return (
    <div style={{ marginLeft: depth > 0 ? 24 : 0 }}>
      <div
        className={`group relative bg-surface rounded-xl border transition-all hover:border-accent/30 ${
          showDetail ? 'border-accent/40 shadow-lg shadow-accent/5' : 'border-border'
        }`}
      >
        {/* Connector line */}
        {depth > 0 && (
          <div className="absolute -left-[13px] top-[22px] w-[13px] h-[2px]" style={{ backgroundColor: node.phaseColor || '#6b7280' }} />
        )}

        <div className="p-3 flex items-center gap-3 cursor-pointer" onClick={() => setShowDetail(!showDetail)}>
          {/* Expand toggle */}
          {hasChildren ? (
            <button
              onClick={e => { e.stopPropagation(); onToggle() }}
              className="p-0.5 rounded hover:bg-surface-2 text-text-muted transition-colors shrink-0"
            >
              {isExpanded ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
            </button>
          ) : (
            <div className="w-4.5" />
          )}

          {/* Phase dot */}
          <div
            className="w-2.5 h-2.5 rounded-full shrink-0 ring-2 ring-offset-1 ring-offset-surface"
            style={{ backgroundColor: node.phaseColor, boxShadow: `0 0 8px ${node.phaseColor}40` }}
          />

          {/* Agent info */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              {emoji && <span className="text-base">{emoji}</span>}
              <span className="text-sm font-semibold truncate">{shortName}</span>
              <span className={`text-[9px] px-1.5 py-0.5 rounded-full border font-medium ${modelBadge.className}`}>
                {modelBadge.label}
              </span>
            </div>
            <div className="flex items-center gap-2 mt-0.5">
              <TierIcon className="w-3 h-3 text-text-muted" />
              <span className="text-[11px] text-text-muted">{node.title}</span>
              {node.phaseLabel && (
                <>
                  <span className="text-text-muted/30">|</span>
                  <span className="text-[10px] font-medium" style={{ color: node.phaseColor }}>{node.phaseLabel}</span>
                </>
              )}
            </div>
          </div>

          {/* Children count badge */}
          {hasChildren && (
            <span className="text-[10px] bg-surface-2 text-text-muted px-1.5 py-0.5 rounded-full shrink-0">
              {children.length}
            </span>
          )}
        </div>

        {/* Detail panel */}
        {showDetail && (
          <div className="px-3 pb-3 pt-0 border-t border-border/50 mt-0">
            <div className="pt-3 space-y-2">
              <p className="text-xs text-text-muted leading-relaxed">{node.description}</p>
              {node.tools && (
                <div className="flex flex-wrap gap-1">
                  {node.tools.split(',').map(t => (
                    <span key={t} className="text-[9px] px-1.5 py-0.5 rounded bg-surface-2 text-text-muted font-mono">
                      {t.trim()}
                    </span>
                  ))}
                </div>
              )}
              {node.reportsTo && (
                <p className="text-[10px] text-text-muted">Reports to: <span className="text-text font-medium">{node.reportsTo}</span></p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default function OrgChartPage() {
  const [data, setData] = useState<OrgChartData | null>(null)
  const [loading, setLoading] = useState(true)
  const [view, setView] = useState<'hierarchy' | 'pipeline'>('pipeline')
  const [expanded, setExpanded] = useState<Set<string>>(new Set(['rex', 'arya']))
  const [search, setSearch] = useState('')

  useEffect(() => {
    getOrgChart().then(setData).catch(() => {}).finally(() => setLoading(false))
  }, [])

  const toggleExpand = (id: string) => {
    setExpanded(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const expandAll = () => {
    if (data) setExpanded(new Set(data.nodes.map(n => n.id)))
  }

  const collapseAll = () => setExpanded(new Set())

  const filteredNodes = useMemo(() => {
    if (!data || !search) return data?.nodes || []
    const q = search.toLowerCase()
    return data.nodes.filter(n =>
      n.name.toLowerCase().includes(q) ||
      n.title.toLowerCase().includes(q) ||
      n.id.toLowerCase().includes(q) ||
      (n.description || '').toLowerCase().includes(q)
    )
  }, [data, search])

  const getChildren = (parentId: string) => {
    if (!data) return []
    const nodeIds = search ? new Set(filteredNodes.map(n => n.id)) : null
    return data.nodes.filter(n => {
      if (n.reportsTo !== parentId) return false
      if (nodeIds && !nodeIds.has(n.id)) return false
      return true
    })
  }

  const renderTree = (parentId: string | null, depth: number): React.ReactNode[] => {
    if (!data) return []
    const children = data.nodes.filter(n => n.reportsTo === parentId)
    if (search) {
      const matchIds = new Set(filteredNodes.map(n => n.id))
      // Show nodes that match OR have matching descendants
      const relevantIds = new Set<string>()
      const addAncestors = (id: string) => {
        relevantIds.add(id)
        const node = data.nodes.find(n => n.id === id)
        if (node?.reportsTo) addAncestors(node.reportsTo)
      }
      filteredNodes.forEach(n => addAncestors(n.id))
      return data.nodes
        .filter(n => n.reportsTo === parentId && relevantIds.has(n.id))
        .map(node => (
          <div key={node.id} className="relative">
            {depth > 0 && (
              <div className="absolute left-[11px] top-0 bottom-0 w-[2px] -translate-y-[2px]" style={{ backgroundColor: `${node.phaseColor}20` }} />
            )}
            <AgentCard
              node={node}
              children={getChildren(node.id)}
              isExpanded={expanded.has(node.id) || matchIds.has(node.id)}
              onToggle={() => toggleExpand(node.id)}
              depth={depth}
            />
            {(expanded.has(node.id) || matchIds.has(node.id)) && (
              <div className="mt-1.5 space-y-1.5 relative">
                {renderTree(node.id, depth + 1)}
              </div>
            )}
          </div>
        ))
    }
    return children.map(node => (
      <div key={node.id} className="relative">
        {depth > 0 && (
          <div className="absolute left-[11px] top-0 bottom-0 w-[2px] -translate-y-[2px]" style={{ backgroundColor: `${node.phaseColor}20` }} />
        )}
        <AgentCard
          node={node}
          children={getChildren(node.id)}
          isExpanded={expanded.has(node.id)}
          onToggle={() => toggleExpand(node.id)}
          depth={depth}
        />
        {expanded.has(node.id) && (
          <div className="mt-1.5 space-y-1.5 relative">
            {renderTree(node.id, depth + 1)}
          </div>
        )}
      </div>
    ))
  }

  if (loading) return <div className="p-8 text-text-muted">Loading org chart...</div>
  if (!data) return <div className="p-8 text-red-400">Failed to load org chart</div>

  return (
    <div className="max-w-6xl mx-auto p-8 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Users className="w-6 h-6" /> Org Chart
          </h1>
          <p className="text-text-muted text-sm mt-1">
            {data.stats.totalAgents} agents &middot; {data.stats.byModel.opus || 0} Opus &middot; {data.stats.byModel.sonnet || 0} Sonnet
          </p>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex bg-surface-2 rounded-lg p-0.5">
            <button
              onClick={() => setView('pipeline')}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${view === 'pipeline' ? 'bg-accent text-white' : 'text-text-muted hover:text-text'}`}
            >
              Pipeline
            </button>
            <button
              onClick={() => setView('hierarchy')}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${view === 'hierarchy' ? 'bg-accent text-white' : 'text-text-muted hover:text-text'}`}
            >
              Hierarchy
            </button>
          </div>
        </div>
      </div>

      {/* Search + controls */}
      <div className="flex items-center gap-3">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-muted" />
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search agents..."
            className="w-full pl-9 pr-3 py-2 text-sm bg-surface border border-border rounded-lg focus:border-accent outline-none"
          />
        </div>
        {view === 'hierarchy' && (
          <div className="flex gap-1">
            <button onClick={expandAll} className="px-2.5 py-1.5 text-[11px] rounded-lg bg-surface-2 text-text-muted hover:text-text">
              Expand All
            </button>
            <button onClick={collapseAll} className="px-2.5 py-1.5 text-[11px] rounded-lg bg-surface-2 text-text-muted hover:text-text">
              Collapse All
            </button>
          </div>
        )}
      </div>

      {/* Pipeline View */}
      {view === 'pipeline' && (
        <div className="space-y-6">
          {/* Pipeline flow indicator */}
          <div className="flex items-center gap-2 overflow-x-auto pb-2">
            {data.phases.map((phase, i) => (
              <div key={phase.id} className="flex items-center gap-2 shrink-0">
                <div
                  className="px-3 py-1.5 rounded-full text-xs font-semibold text-white"
                  style={{ backgroundColor: phase.color }}
                >
                  {phase.label}
                </div>
                {i < data.phases.length - 1 && (
                  <div className="w-6 h-[2px] bg-border" />
                )}
              </div>
            ))}
          </div>

          {/* Phase cards */}
          {data.phases.map(phase => {
            const agents = search
              ? phase.agents.filter(a =>
                  a.name.toLowerCase().includes(search.toLowerCase()) ||
                  a.title.toLowerCase().includes(search.toLowerCase()) ||
                  a.id.toLowerCase().includes(search.toLowerCase())
                )
              : phase.agents
            if (search && agents.length === 0) return null
            return (
              <div key={phase.id} className="bg-surface rounded-2xl border border-border overflow-hidden">
                <div className="px-5 py-3 border-b border-border flex items-center gap-3" style={{ borderLeftWidth: 4, borderLeftColor: phase.color }}>
                  <div>
                    <h2 className="text-sm font-bold" style={{ color: phase.color }}>{phase.label}</h2>
                    <p className="text-[11px] text-text-muted">{phase.description}</p>
                  </div>
                  <span className="ml-auto text-[10px] bg-surface-2 text-text-muted px-2 py-0.5 rounded-full">{agents.length} agents</span>
                </div>
                <div className="p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                  {agents.map(agent => {
                    const emoji = agent.name.match(/^(\p{Emoji_Presentation}|\p{Extended_Pictographic})/u)?.[0] || ''
                    const shortName = agent.name.replace(/^[\p{Emoji_Presentation}\p{Extended_Pictographic}]\s*[\u200d\ufe0f]*/u, '').replace(/^—\s*/, '').split('—')[0]?.trim()
                    const badge = MODEL_BADGES[agent.model] || { label: agent.model, className: 'bg-surface-2 text-text-muted' }
                    return (
                      <div key={agent.id} className="bg-surface-2/50 rounded-xl p-3 border border-border/50 hover:border-border transition-colors">
                        <div className="flex items-center gap-2 mb-1.5">
                          {emoji && <span className="text-lg">{emoji}</span>}
                          <span className="text-sm font-semibold">{shortName}</span>
                          <span className={`text-[9px] px-1.5 py-0.5 rounded-full border font-medium ml-auto ${badge.className}`}>
                            {badge.label}
                          </span>
                        </div>
                        <p className="text-[11px] text-text-muted font-medium mb-1">{agent.title}</p>
                        <p className="text-[10px] text-text-muted leading-relaxed line-clamp-2">{agent.description}</p>
                      </div>
                    )
                  })}
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* Hierarchy View */}
      {view === 'hierarchy' && (
        <div className="space-y-2">
          {/* Leadership (no parent) */}
          {renderTree(null, 0)}
        </div>
      )}

      {/* Stats footer */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {Object.entries(data.stats.byTier).sort(([,a],[,b]) => b - a).map(([tier, count]) => {
          const TIcon = TIER_ICONS[tier] || Cpu
          return (
            <div key={tier} className="bg-surface rounded-xl border border-border p-3 flex items-center gap-3">
              <TIcon className="w-4 h-4 text-text-muted" />
              <div>
                <div className="text-xs font-semibold capitalize">{tier}</div>
                <div className="text-[10px] text-text-muted">{count} agents</div>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

