  SHAPE: {
    label: 'Shape',
    description: 'Validate ideas before investing time',
    color: '#f59e0b',
    agents: ['scout', 'vex', 'sage'],
  },
  VALIDATE: {
    label: 'Validate',
    description: 'Market sizing, architecture, pricing',
    color: '#8b5cf6',
    agents: ['atlas', 'arya', 'riko', 'ledger'],
  },
  BUILD: {
    label: 'Build',
    description: 'Production code, tests, design, copy',
    color: '#3b82f6',
    agents: ['rex', 'nova', 'koda', 'luna', 'quill', 'vega', 'zeph'],
  },
  LAUNCH: {
    label: 'Launch',
    description: 'Distribution, deployment, monitoring',
    color: '#10b981',
    agents: ['echo', 'mira', 'bolt', 'hawk'],
