  rex: { title: 'Commander', reportsTo: null, tier: 'leadership' },
  scout: { title: 'Idea Validator', reportsTo: 'rex', tier: 'analyst' },
  vex: { title: 'Bug Fixer', reportsTo: 'rex', tier: 'engineer' },
  sage: { title: 'Code Reviewer', reportsTo: 'rex', tier: 'engineer' },
  atlas: { title: 'Market Sizer', reportsTo: 'rex', tier: 'analyst' },
  arya: { title: 'Architect', reportsTo: 'rex', tier: 'leadership' },
  riko: { title: 'Project Setup', reportsTo: 'arya', tier: 'engineer' },
  ledger: { title: 'Pricing Strategist', reportsTo: 'rex', tier: 'analyst' },
  nova: { title: 'Market Researcher', reportsTo: 'rex', tier: 'analyst' },
  koda: { title: 'Feature Builder', reportsTo: 'arya', tier: 'engineer' },
  luna: { title: 'Test Engineer', reportsTo: 'sage', tier: 'engineer' },
  quill: { title: 'Content Writer', reportsTo: 'rex', tier: 'creative' },
  vega: { title: 'UI/UX Designer', reportsTo: 'rex', tier: 'creative' },
  zeph: { title: 'SEO Specialist', reportsTo: 'quill', tier: 'creative' },
  echo: { title: 'Distribution Planner', reportsTo: 'rex', tier: 'analyst' },
  mira: { title: 'Knowledge Manager', reportsTo: 'rex', tier: 'analyst' },
  bolt: { title: 'DevOps Engineer', reportsTo: 'arya', tier: 'engineer' },
  hawk: { title: 'Ops Monitor', reportsTo: 'bolt', tier: 'engineer' },
  orbit: { title: 'Metrics Architect', reportsTo: 'rex', tier: 'analyst' },
  pulse: { title: 'User Researcher', reportsTo: 'orbit', tier: 'analyst' },
  verdict: { title: 'Portfolio Decider', reportsTo: null, tier: 'leadership' },
};

app.get('/api/org-chart', rateLimit('read'), (req, res) => {
  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  const agentMap = {};
  for (const a of globalAgents) {
    agentMap[a.filename] = a;
  }

  // Build hierarchy nodes
  const nodes = [];
  for (const [filename, agentData] of Object.entries(agentMap)) {
    const role = AGENT_ROLES[filename] || { title: 'Agent', reportsTo: 'rex', tier: 'engineer' };
    let phase = null;
    for (const [phaseName, phaseData] of Object.entries(AGENT_PIPELINE)) {
      if (phaseData.agents.includes(filename)) {
        phase = phaseName;
        break;
      }
    }
    nodes.push({
      id: filename,
      name: agentData.name,
      title: role.title,
      model: agentData.model,
      tools: agentData.tools,
      description: agentData.description,
      phase,
      phaseLabel: phase ? AGENT_PIPELINE[phase].label : null,
      phaseColor: phase ? AGENT_PIPELINE[phase].color : '#6b7280',
      reportsTo: role.reportsTo,
      tier: role.tier,
    });
  }

  // Build edges (reporting lines)
  const edges = [];
  for (const node of nodes) {
    if (node.reportsTo && agentMap[node.reportsTo]) {
      edges.push({ from: node.reportsTo, to: node.id });
    }
  }

  // Build pipeline phases
  const phases = Object.entries(AGENT_PIPELINE).map(([key, data]) => ({
    id: key,
    label: data.label,
    description: data.description,
    color: data.color,
    agents: data.agents.filter(a => agentMap[a]).map(a => ({
      id: a,
      name: agentMap[a]?.name || a,
      title: AGENT_ROLES[a]?.title || 'Agent',
      model: agentMap[a]?.model || 'sonnet',
      description: agentMap[a]?.description || '',
    })),
  }));

  // Stats
  const stats = {
    totalAgents: nodes.length,
    byModel: {},
    byTier: {},
    byPhase: {},
  };
  for (const n of nodes) {
    stats.byModel[n.model] = (stats.byModel[n.model] || 0) + 1;
    stats.byTier[n.tier] = (stats.byTier[n.tier] || 0) + 1;
    if (n.phase) stats.byPhase[n.phase] = (stats.byPhase[n.phase] || 0) + 1;
  }

  res.json({ nodes, edges, phases, stats });
});

