}

const SHAPES = [
  ShapeOrb, ShapeGem, ShapeNetwork, ShapeSpiral,
  ShapeLightning, ShapeWaves, ShapeEye, ShapeCompass,
]

// ─── Pixel-art icon for global agents ───────────────────────────────────────

// Vivid gradient palettes for global agent cards
const GLOBAL_PALETTES: [string, string][] = [
  ['#7c3aed', '#4f46e5'],
  ['#0ea5e9', '#6366f1'],
  ['#ec4899', '#f97316'],
  ['#10b981', '#0891b2'],
  ['#f59e0b', '#ef4444'],
  ['#14b8a6', '#3b82f6'],
  ['#a855f7', '#ec4899'],
  ['#06b6d4', '#8b5cf6'],
]

function PixelArtIcon({ name, size }: { name: string; size: number }) {
  const seed = encodeURIComponent(name.toLowerCase().replace(/[^a-z0-9-]/g, '-'))
  const [c1, c2] = GLOBAL_PALETTES[nameHash(name) % GLOBAL_PALETTES.length]
  const imgSize = Math.round(size * 1.05)

  return (
    <div
      className="shrink-0 rounded-xl border border-white/20 shadow-md overflow-hidden"
      style={{
        width: size,
        height: size,
        background: `linear-gradient(160deg, ${c1} 0%, ${c2} 100%)`,
        display: 'flex',
        alignItems: 'flex-end',
        justifyContent: 'center',
        flexShrink: 0,
        position: 'relative',
      }}
    >
      <img
        src={`https://api.dicebear.com/9.x/pixel-art/svg?seed=${seed}&size=${imgSize * 2}&backgroundColor=transparent`}
        alt={name}
        width={imgSize}
        height={imgSize}
        loading="lazy"
        decoding="async"
        style={{ display: 'block', imageRendering: 'pixelated' }}
      />
    </div>
  )
}

// ─── Unified card wrapper for project abstract icons ─────────────────────────

function AbstractIcon({
  name, uid, size, c1, c2,
}: { name: string; uid: string; size: number; c1: string; c2: string }) {
  const Shape = SHAPES[nameHash(name) % SHAPES.length]
  const pad = Math.round(size * 0.14)
  const inner = size - pad * 2

  return (
    <div
      className="shrink-0 rounded-xl border border-white/15 shadow-md"
      style={{
        width: size,
        height: size,
        background: `linear-gradient(135deg, ${c1} 0%, ${c2} 100%)`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: pad,
        boxSizing: 'border-box',
        flexShrink: 0,
      }}
    >
      <div style={{ width: inner, height: inner }}>
        <Shape key={uid} />
      </div>
    </div>
  )
}

// ─── Public component ────────────────────────────────────────────────────────

interface AgentIconProps {
  name: string
  /** Unique key to prevent SVG gradient ID collisions when duplicates appear */
  uid?: string
  className?: string
  size?: number
  /** Render pixel-art character (global agents) */
  global?: boolean
}

export default function AgentIcon({
  name, uid, className = '', size = 40, global: isGlobal = false,
}: AgentIconProps) {
  const safeUid = (uid || name).replace(/[^a-z0-9]/gi, '-').slice(0, 28)

  if (isGlobal) {
    return (
      <div className={className} style={{ flexShrink: 0 }}>
        <PixelArtIcon name={name} size={size} />
      </div>
    )
  }

  const h = nameHash(name)
  const [c1, c2] = PALETTES[(h >> 4) % PALETTES.length]

  return (
    <div className={className} style={{ flexShrink: 0 }}>
      <AbstractIcon name={name} uid={safeUid} size={size} c1={c1} c2={c2} />
    </div>
  )
}

export const getProjectActivity = (projectId: string, limit?: number) =>
  request<{ total: number; runs: AgentRunEntry[] }>(`/projects/${projectId}/activity${limit ? `?limit=${limit}` : ''}`)

// ── Org Chart ────────────────────────────────────────────────────────────────
export interface OrgChartNode {
  id: string
  name: string
  title: string
  model: string
  tools: string
  description: string
  phase: string | null
  phaseLabel: string | null
  phaseColor: string
  reportsTo: string | null
  tier: string
}

export interface OrgChartEdge {
  from: string
  to: string
}

export interface OrgChartPhase {
  id: string
  label: string
  description: string
  color: string
  agents: { id: string; name: string; title: string; model: string; description: string }[]
}

export interface OrgChartData {
  nodes: OrgChartNode[]
  edges: OrgChartEdge[]
  phases: OrgChartPhase[]
  stats: {
    totalAgents: number
    byModel: Record<string, number>
    byTier: Record<string, number>
    byPhase: Record<string, number>
  }
}

export const getOrgChart = () => request<OrgChartData>('/org-chart')

// ── Goal Cascade ─────────────────────────────────────────────────────────────
export interface ProjectGoal {
  id: string
  projectId: string
  projectName: string

