import { useState, useEffect, useMemo, useCallback, memo } from 'react'
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
  type Node,
  type Edge,
  type NodeTypes,
  Handle,
  Position,
  BackgroundVariant,
  useReactFlow,
  ReactFlowProvider,
  type NodeProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import {
  Users, Search, Cpu, Paintbrush, BarChart3, Shield,
  X, ChevronDown, ChevronRight, GitBranch, LayoutGrid, List,
} from 'lucide-react'
import { getOrgChart } from '../lib/api'
import type { OrgChartData, OrgChartNode } from '../lib/api'
import AgentIcon from '../components/AgentIcon'

// ── Constants ────────────────────────────────────────────────────────────────

const NODE_WIDTH = 220
const NODE_HEIGHT = 96
const H_GAP = 32
const LEVEL_HEIGHT = 150
const ROOT_GAP = 120

const TIER_ICONS: Record<string, typeof Cpu> = {
  leadership: Shield,
  engineer: Cpu,
  analyst: BarChart3,
  creative: Paintbrush,
}

const MODEL_BADGES: Record<string, { label: string; bg: string; text: string; border: string }> = {
  opus: { label: 'Opus', bg: 'rgba(168,85,247,0.15)', text: '#c084fc', border: 'rgba(168,85,247,0.3)' },
  sonnet: { label: 'Sonnet', bg: 'rgba(96,165,250,0.15)', text: '#60a5fa', border: 'rgba(96,165,250,0.3)' },
}

function extractEmoji(name: string): { emoji: string; cleanName: string } {
  const emoji = name.match(/^(\p{Emoji_Presentation}|\p{Extended_Pictographic})/u)?.[0] || ''
  const cleanName = name
    .replace(/^[\p{Emoji_Presentation}\p{Extended_Pictographic}]\s*[\u200d\ufe0f]*/u, '')
    .replace(/^—\s*/, '')
    .trim()
  return { emoji, cleanName: cleanName.split('—')[0]?.trim() || cleanName }
}

// ── Tree Layout Algorithm ────────────────────────────────────────────────────

interface LayoutResult {
  width: number
  nodes: Array<{ id: string; x: number; y: number }>
  edges: Array<{ source: string; target: string }>
}

function layoutSubtree(
  nodeId: string,
  allNodes: OrgChartNode[],
  depth: number,
): LayoutResult {
  const children = allNodes.filter(n => n.reportsTo === nodeId)

  if (children.length === 0) {
    return {
      width: NODE_WIDTH,
      nodes: [{ id: nodeId, x: 0, y: depth * LEVEL_HEIGHT }],
      edges: [],
    }
  }

  const childLayouts = children.map(c => layoutSubtree(c.id, allNodes, depth + 1))
  const totalChildWidth = childLayouts.reduce((sum, l) => sum + l.width, 0)
    + (children.length - 1) * H_GAP

  // Position children left to right
  let currentX = 0
  const allChildNodes: LayoutResult['nodes'] = []
  const allChildEdges: LayoutResult['edges'] = []

  for (let i = 0; i < childLayouts.length; i++) {
    const layout = childLayouts[i]
    for (const node of layout.nodes) {
      allChildNodes.push({ ...node, x: node.x + currentX })
    }
    allChildEdges.push(...layout.edges)
    allChildEdges.push({ source: nodeId, target: children[i].id })
    currentX += layout.width + H_GAP
  }

  // Center parent over children
  const subtreeWidth = Math.max(totalChildWidth, NODE_WIDTH)
  const parentX = totalChildWidth / 2 - NODE_WIDTH / 2

  return {
    width: subtreeWidth,
    nodes: [{ id: nodeId, x: parentX, y: depth * LEVEL_HEIGHT }, ...allChildNodes],
    edges: allChildEdges,
  }
}

function computeTreeLayout(allNodes: OrgChartNode[]): {
  rfNodes: Node<OrgAgentNodeData>[]
  rfEdges: Edge[]
} {
  const roots = allNodes.filter(n => n.reportsTo === null)
  const nodeMap = new Map(allNodes.map(n => [n.id, n]))

  // Layout each root subtree
  const subtrees = roots.map(r => layoutSubtree(r.id, allNodes, 0))

  // Place subtrees side by side
  let offsetX = 0
  const finalNodes: Array<{ id: string; x: number; y: number }> = []
  const finalEdges: Array<{ source: string; target: string }> = []

  for (const subtree of subtrees) {
    for (const node of subtree.nodes) {
      finalNodes.push({ ...node, x: node.x + offsetX })
    }
    finalEdges.push(...subtree.edges)
    offsetX += subtree.width + ROOT_GAP
  }

  // Convert to ReactFlow format
  const rfNodes: Node<OrgAgentNodeData>[] = finalNodes.map(pos => {
    const node = nodeMap.get(pos.id)!
    const { emoji, cleanName } = extractEmoji(node.name)
    const childCount = allNodes.filter(n => n.reportsTo === node.id).length

    return {
      id: pos.id,
      type: 'orgAgent',
      position: { x: pos.x, y: pos.y },
      data: {
        agentId: node.id,
        name: cleanName,
        emoji,
        title: node.title,
        model: node.model,
        tier: node.tier,
        phaseColor: node.phaseColor,
        phaseLabel: node.phaseLabel,
        description: node.description,
        tools: node.tools,
        reportsTo: node.reportsTo,
        childCount,
        dimmed: false,
      },
    }
  })

  const rfEdges: Edge[] = finalEdges.map(e => ({
    id: `e-${e.source}-${e.target}`,
    source: e.source,
    target: e.target,
    type: 'smoothstep',
    style: {
      stroke: nodeMap.get(e.target)?.phaseColor || 'var(--color-border)',
      strokeWidth: 2,
      opacity: 0.6,
    },
  }))

  return { rfNodes, rfEdges }
}

// ── Custom ReactFlow Node ────────────────────────────────────────────────────

interface OrgAgentNodeData {
  agentId: string
  name: string
  emoji: string
  title: string
  model: string
  tier: string
  phaseColor: string
  phaseLabel: string | null
  description: string
  tools: string
  reportsTo: string | null
  childCount: number
  dimmed: boolean
  [key: string]: unknown
}

const OrgChartAgentNode = memo(function OrgChartAgentNode({
  data,
  selected,
}: NodeProps<Node<OrgAgentNodeData>>) {
  const badge = MODEL_BADGES[data.model]
  const TierIcon = TIER_ICONS[data.tier] || Cpu

  return (
    <div
      className="transition-all duration-200"
      style={{ opacity: data.dimmed ? 0.2 : 1 }}
    >
      <Handle
        type="target"
        position={Position.Top}
        className="!w-2 !h-2 !bg-transparent !border-0 !top-0"
      />

      <div
        className={`relative rounded-xl border-2 bg-surface backdrop-blur-sm transition-all duration-200 cursor-pointer
          ${selected
            ? 'shadow-lg ring-2 ring-accent/40 ring-offset-2 ring-offset-bg'
            : 'shadow-md hover:shadow-lg hover:border-accent/30'
          }`}
        style={{
          width: NODE_WIDTH,
          minHeight: NODE_HEIGHT,
          borderColor: selected ? 'var(--color-accent)' : 'var(--color-border)',
          borderLeftWidth: 4,
          borderLeftColor: data.phaseColor,
        }}
      >
        <div className="px-3.5 py-3">
          {/* Top row: icon + name + model badge */}
          <div className="flex items-center gap-2.5 mb-1.5">
            <AgentIcon
              name={data.name}
              uid={`org-${data.agentId}`}
              size={32}
              global
            />
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-1.5">
                <span className="text-[13px] font-bold truncate leading-tight">{data.name}</span>
                {badge && (
                  <span
                    className="text-[9px] px-1.5 py-0.5 rounded-full font-semibold shrink-0"
                    style={{
                      backgroundColor: badge.bg,
                      color: badge.text,
                      border: `1px solid ${badge.border}`,
                    }}
                  >
                    {badge.label}
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Bottom row: tier icon + title + phase */}
          <div className="flex items-center gap-1.5 ml-[42px]">
            <TierIcon className="w-3 h-3 text-text-muted shrink-0" />
            <span className="text-[11px] text-text-muted truncate">{data.title}</span>
            {data.phaseLabel && (
              <>
                <span className="text-text-muted/30 shrink-0">&middot;</span>
                <span
                  className="text-[10px] font-semibold shrink-0"
                  style={{ color: data.phaseColor }}
                >
                  {data.phaseLabel}
                </span>
              </>
            )}
          </div>

          {/* Child count badge */}
          {data.childCount > 0 && (
            <div
              className="absolute -bottom-2.5 left-1/2 -translate-x-1/2 text-[9px] font-bold px-2 py-0.5 rounded-full border-2 border-surface bg-surface-2 text-text-muted"
            >
              {data.childCount}
            </div>
          )}
        </div>
      </div>

      <Handle
        type="source"
        position={Position.Bottom}
        className="!w-2 !h-2 !bg-transparent !border-0 !bottom-0"
      />
    </div>
  )
})

const nodeTypes: NodeTypes = { orgAgent: OrgChartAgentNode }

// ── Detail Panel ─────────────────────────────────────────────────────────────

function DetailPanel({
  node,
  allNodes,
  onClose,
  onNavigate,
}: {
  node: OrgChartNode
  allNodes: OrgChartNode[]
  onClose: () => void
  onNavigate: (id: string) => void
}) {
  const { emoji, cleanName } = extractEmoji(node.name)
  const badge = MODEL_BADGES[node.model]
  const TierIcon = TIER_ICONS[node.tier] || Cpu
  const directReports = allNodes.filter(n => n.reportsTo === node.id)
  const reportsToNode = node.reportsTo ? allNodes.find(n => n.id === node.reportsTo) : null

  return (
    <div className="absolute top-0 right-0 w-[340px] h-full bg-surface border-l border-border z-20 overflow-y-auto shadow-2xl animate-slide-in">
      {/* Header */}
      <div className="sticky top-0 bg-surface border-b border-border px-5 py-4 flex items-start gap-3">
        <AgentIcon name={cleanName} uid={`detail-${node.id}`} size={44} global />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            {emoji && <span className="text-xl">{emoji}</span>}
            <h3 className="text-base font-bold truncate">{cleanName}</h3>
          </div>
          <div className="flex items-center gap-1.5 mt-0.5">
            <TierIcon className="w-3.5 h-3.5 text-text-muted" />
            <span className="text-xs text-text-muted">{node.title}</span>
          </div>
        </div>
        <button
          onClick={onClose}
          className="p-1.5 rounded-lg hover:bg-surface-2 text-text-muted transition-colors shrink-0"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="px-5 py-4 space-y-5">
        {/* Badges row */}
        <div className="flex items-center gap-2 flex-wrap">
          {badge && (
            <span
              className="text-xs px-2.5 py-1 rounded-full font-semibold"
              style={{ backgroundColor: badge.bg, color: badge.text, border: `1px solid ${badge.border}` }}
            >
              {badge.label}
            </span>
          )}
          {node.phaseLabel && (
            <span
              className="text-xs px-2.5 py-1 rounded-full font-semibold"
              style={{
                backgroundColor: `${node.phaseColor}20`,
                color: node.phaseColor,
                border: `1px solid ${node.phaseColor}40`,
              }}
            >
              {node.phaseLabel}
            </span>
          )}
          <span className="text-xs px-2.5 py-1 rounded-full font-medium bg-surface-2 text-text-muted capitalize">
            {node.tier}
          </span>
        </div>

        {/* Description */}
        {node.description && (
          <div>
            <p className="text-[11px] uppercase tracking-wider text-text-muted font-semibold mb-1.5">Description</p>
            <p className="text-sm text-text-secondary leading-relaxed">{node.description}</p>
          </div>
        )}

        {/* Tools */}
        {node.tools && (
          <div>
            <p className="text-[11px] uppercase tracking-wider text-text-muted font-semibold mb-1.5">Tools</p>
            <div className="flex flex-wrap gap-1.5">
              {node.tools.split(',').map(t => (
                <span key={t.trim()} className="text-[11px] px-2 py-0.5 rounded-md bg-surface-2 text-text-muted font-mono">
                  {t.trim()}
                </span>
              ))}
            </div>
          </div>
        )}

        {/* Reports to */}
        {reportsToNode && (
          <div>
            <p className="text-[11px] uppercase tracking-wider text-text-muted font-semibold mb-1.5">Reports to</p>
            <button
              onClick={() => onNavigate(reportsToNode.id)}
              className="flex items-center gap-2 px-3 py-2 rounded-lg bg-surface-2 hover:bg-surface-3 transition-colors w-full text-left"
            >
              <AgentIcon name={extractEmoji(reportsToNode.name).cleanName} uid={`rpt-${reportsToNode.id}`} size={24} global />
              <div>
                <span className="text-xs font-semibold">{extractEmoji(reportsToNode.name).cleanName}</span>
                <span className="text-[10px] text-text-muted block">{reportsToNode.title}</span>
              </div>
            </button>
          </div>
        )}

        {/* Direct reports */}
        {directReports.length > 0 && (
          <div>
            <p className="text-[11px] uppercase tracking-wider text-text-muted font-semibold mb-1.5">
              Direct reports ({directReports.length})
            </p>
            <div className="space-y-1.5">
              {directReports.map(r => {
                const { cleanName: rName } = extractEmoji(r.name)
                return (
                  <button
                    key={r.id}
                    onClick={() => onNavigate(r.id)}
                    className="flex items-center gap-2 px-3 py-2 rounded-lg bg-surface-2 hover:bg-surface-3 transition-colors w-full text-left"
                  >
                    <AgentIcon name={rName} uid={`dr-${r.id}`} size={24} global />
                    <div className="min-w-0">
                      <span className="text-xs font-semibold truncate block">{rName}</span>
                      <span className="text-[10px] text-text-muted">{r.title}</span>
                    </div>
                    <div
                      className="w-2 h-2 rounded-full ml-auto shrink-0"
                      style={{ backgroundColor: r.phaseColor }}
                    />
                  </button>
                )
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

// ── Tree View (ReactFlow) ────────────────────────────────────────────────────

function TreeViewInner({
  data,
  search,
  selectedNode,
  onSelectNode,
}: {
  data: OrgChartData
  search: string
  selectedNode: string | null
  onSelectNode: (id: string | null) => void
}) {
  const { rfNodes: initialNodes, rfEdges: initialEdges } = useMemo(
    () => computeTreeLayout(data.nodes),
    [data.nodes],
  )

  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes)
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges)
  const reactFlowInstance = useReactFlow()

  // Apply search dimming
  useEffect(() => {
    if (!search) {
      setNodes(nds =>
        nds.map(n => ({ ...n, data: { ...n.data, dimmed: false } })),
      )
      setEdges(eds =>
        eds.map(e => ({
          ...e,
          style: { ...e.style, opacity: 0.6 },
        })),
      )
      return
    }

    const q = search.toLowerCase()
    const matchIds = new Set(
      data.nodes
        .filter(n =>
          n.name.toLowerCase().includes(q)
          || n.title.toLowerCase().includes(q)
          || n.id.toLowerCase().includes(q)
          || (n.description || '').toLowerCase().includes(q),
        )
        .map(n => n.id),
    )

    // Include ancestors of matches
    const relevantIds = new Set<string>()
    const addAncestors = (id: string) => {
      relevantIds.add(id)
      const node = data.nodes.find(n => n.id === id)
      if (node?.reportsTo) addAncestors(node.reportsTo)
    }
    matchIds.forEach(id => addAncestors(id))

    setNodes(nds =>
      nds.map(n => ({
        ...n,
        data: { ...n.data, dimmed: !relevantIds.has(n.id) },
      })),
    )
    setEdges(eds =>
      eds.map(e => ({
        ...e,
        style: {
          ...e.style,
          opacity: relevantIds.has(e.source) && relevantIds.has(e.target) ? 0.6 : 0.08,
        },
      })),
    )

    // Fit view to matching nodes
    const matchingNodes = nodes.filter(n => matchIds.has(n.id))
    if (matchingNodes.length > 0) {
      setTimeout(() => {
        reactFlowInstance.fitView({
          nodes: matchingNodes,
          padding: 0.4,
          duration: 400,
        })
      }, 50)
    }
  }, [search, data.nodes, setNodes, setEdges, reactFlowInstance, nodes])

  const handleNodeClick = useCallback(
    (_: React.MouseEvent, node: Node<OrgAgentNodeData>) => {
      onSelectNode(node.id === selectedNode ? null : node.id)
    },
    [onSelectNode, selectedNode],
  )

  const handlePaneClick = useCallback(() => {
    onSelectNode(null)
  }, [onSelectNode])

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      onEdgesChange={onEdgesChange}
      onNodeClick={handleNodeClick}
      onPaneClick={handlePaneClick}
      nodeTypes={nodeTypes}
      nodesDraggable={false}
      nodesConnectable={false}
      elementsSelectable
      fitView
      fitViewOptions={{ padding: 0.3 }}
      minZoom={0.2}
      maxZoom={1.5}
      proOptions={{ hideAttribution: true }}
      className="bg-bg"
    >
      <Background variant={BackgroundVariant.Dots} gap={20} size={1} className="!bg-bg" />
      <Controls
        showInteractive={false}
        className="!bg-surface !border-border !rounded-xl !shadow-lg [&>button]:!bg-surface [&>button]:!border-border [&>button]:!text-text-muted [&>button:hover]:!bg-surface-2"
      />
      <MiniMap
        nodeColor={(n) => {
          const nodeData = n.data as OrgAgentNodeData
          return nodeData.phaseColor || '#6b7280'
        }}
        maskColor="rgba(0,0,0,0.2)"
        className="!bg-surface !border-border !rounded-xl"
        pannable
        zoomable
      />
    </ReactFlow>
  )
}

function TreeView(props: {
  data: OrgChartData
  search: string
  selectedNode: string | null
  onSelectNode: (id: string | null) => void
}) {
  return (
    <ReactFlowProvider>
      <TreeViewInner {...props} />
    </ReactFlowProvider>
  )
}

// ── Pipeline View ────────────────────────────────────────────────────────────

function PipelineView({ data, search }: { data: OrgChartData; search: string }) {
  return (
    <div className="space-y-6">
      {/* Pipeline flow indicator */}
      <div className="flex items-center gap-2 overflow-x-auto pb-2">
        {data.phases.map((phase, i) => (
          <div key={phase.id} className="flex items-center gap-2 shrink-0">
            <div
              className="px-3.5 py-1.5 rounded-full text-xs font-bold text-white shadow-sm"
              style={{ backgroundColor: phase.color }}
            >
              {phase.label}
            </div>
            {i < data.phases.length - 1 && (
              <div className="w-8 h-[2px] bg-border" />
            )}
          </div>
        ))}
      </div>

      {/* Phase cards */}
      {data.phases.map(phase => {
        const agents = search
          ? phase.agents.filter(a =>
              a.name.toLowerCase().includes(search.toLowerCase())
              || a.title.toLowerCase().includes(search.toLowerCase())
              || a.id.toLowerCase().includes(search.toLowerCase()),
            )
          : phase.agents
        if (search && agents.length === 0) return null
        return (
          <div key={phase.id} className="bg-surface rounded-2xl border border-border overflow-hidden">
            <div
              className="px-5 py-3 border-b border-border flex items-center gap-3"
              style={{ borderLeftWidth: 4, borderLeftColor: phase.color }}
            >
              <div>
                <h2 className="text-sm font-bold" style={{ color: phase.color }}>{phase.label}</h2>
                <p className="text-[11px] text-text-muted">{phase.description}</p>
              </div>
              <span className="ml-auto text-[10px] bg-surface-2 text-text-muted px-2 py-0.5 rounded-full">
                {agents.length} agents
              </span>
            </div>
            <div className="p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
              {agents.map(agent => {
                const { emoji, cleanName } = extractEmoji(agent.name)
                const badge = MODEL_BADGES[agent.model]
                return (
                  <div
                    key={agent.id}
                    className="bg-surface-2/50 rounded-xl p-3.5 border border-border/50 hover:border-border hover:shadow-md transition-all"
                  >
                    <div className="flex items-center gap-2.5 mb-2">
                      <AgentIcon name={cleanName} uid={`pipe-${agent.id}`} size={28} global />
                      <span className="text-sm font-semibold truncate">{cleanName}</span>
                      {badge && (
                        <span
                          className="text-[9px] px-1.5 py-0.5 rounded-full font-semibold ml-auto shrink-0"
                          style={{ backgroundColor: badge.bg, color: badge.text, border: `1px solid ${badge.border}` }}
                        >
                          {badge.label}
                        </span>
                      )}
                    </div>
                    <p className="text-[11px] text-text-muted font-medium mb-1">{agent.title}</p>
                    <p className="text-[10px] text-text-muted leading-relaxed line-clamp-2">{agent.description}</p>
                  </div>
                )
              })}
            </div>
          </div>
        )
      })}
    </div>
  )
}

// ── List View (Hierarchy) ────────────────────────────────────────────────────

function ListAgentCard({ node, depth }: { node: OrgChartNode; depth: number }) {
  const [showDetail, setShowDetail] = useState(false)
  const { emoji, cleanName } = extractEmoji(node.name)
  const badge = MODEL_BADGES[node.model]
  const TierIcon = TIER_ICONS[node.tier] || Cpu

  return (
    <div style={{ marginLeft: depth > 0 ? 24 : 0 }}>
      <div
        className={`group relative bg-surface rounded-xl border transition-all hover:border-accent/30 cursor-pointer ${
          showDetail ? 'border-accent/40 shadow-lg shadow-accent/5' : 'border-border'
        }`}
        onClick={() => setShowDetail(!showDetail)}
      >
        {depth > 0 && (
          <div
            className="absolute -left-[13px] top-[22px] w-[13px] h-[2px]"
            style={{ backgroundColor: node.phaseColor || '#6b7280' }}
          />
        )}

        <div className="p-3 flex items-center gap-3">
          <div
            className="w-2.5 h-2.5 rounded-full shrink-0 ring-2 ring-offset-1 ring-offset-surface"
            style={{ backgroundColor: node.phaseColor, boxShadow: `0 0 8px ${node.phaseColor}40` }}
          />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              {emoji && <span className="text-base">{emoji}</span>}
              <span className="text-sm font-semibold truncate">{cleanName}</span>
              {badge && (
                <span
                  className="text-[9px] px-1.5 py-0.5 rounded-full font-medium"
                  style={{ backgroundColor: badge.bg, color: badge.text, border: `1px solid ${badge.border}` }}
                >
                  {badge.label}
                </span>
              )}
            </div>
            <div className="flex items-center gap-2 mt-0.5">
              <TierIcon className="w-3 h-3 text-text-muted" />
              <span className="text-[11px] text-text-muted">{node.title}</span>
              {node.phaseLabel && (
                <>
                  <span className="text-text-muted/30">|</span>
                  <span className="text-[10px] font-medium" style={{ color: node.phaseColor }}>{node.phaseLabel}</span>
                </>
              )}
            </div>
          </div>
        </div>

        {showDetail && (
          <div className="px-3 pb-3 pt-0 border-t border-border/50">
            <div className="pt-3 space-y-2">
              <p className="text-xs text-text-muted leading-relaxed">{node.description}</p>
              {node.tools && (
                <div className="flex flex-wrap gap-1">
                  {node.tools.split(',').map(t => (
                    <span key={t} className="text-[9px] px-1.5 py-0.5 rounded bg-surface-2 text-text-muted font-mono">
                      {t.trim()}
                    </span>
                  ))}
                </div>
              )}
              {node.reportsTo && (
                <p className="text-[10px] text-text-muted">
                  Reports to: <span className="text-text font-medium">{node.reportsTo}</span>
                </p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

function ListView({
  data,
  search,
  expanded,
  onToggleExpand,
}: {
  data: OrgChartData
  search: string
  expanded: Set<string>
  onToggleExpand: (id: string) => void
}) {
  const filteredNodes = useMemo(() => {
    if (!search) return data.nodes
    const q = search.toLowerCase()
    return data.nodes.filter(n =>
      n.name.toLowerCase().includes(q)
      || n.title.toLowerCase().includes(q)
      || n.id.toLowerCase().includes(q)
      || (n.description || '').toLowerCase().includes(q),
    )
  }, [data.nodes, search])

  const renderTree = (parentId: string | null, depth: number): React.ReactNode[] => {
    const children = data.nodes.filter(n => n.reportsTo === parentId)

    if (search) {
      const matchIds = new Set(filteredNodes.map(n => n.id))
      const relevantIds = new Set<string>()
      const addAncestors = (id: string) => {
        relevantIds.add(id)
        const node = data.nodes.find(n => n.id === id)
        if (node?.reportsTo) addAncestors(node.reportsTo)
      }
      filteredNodes.forEach(n => addAncestors(n.id))

      return children
        .filter(n => relevantIds.has(n.id))
        .map(node => {
          const nodeChildren = data.nodes.filter(n => n.reportsTo === node.id && relevantIds.has(n.id))
          const isOpen = expanded.has(node.id) || matchIds.has(node.id)
          return (
            <div key={node.id} className="relative">
              {depth > 0 && (
                <div className="absolute left-[11px] top-0 bottom-0 w-[2px]" style={{ backgroundColor: `${node.phaseColor}20` }} />
              )}
              <div className="flex items-center gap-1">
                {nodeChildren.length > 0 && (
                  <button
                    onClick={() => onToggleExpand(node.id)}
                    className="p-0.5 rounded hover:bg-surface-2 text-text-muted shrink-0"
                  >
                    {isOpen ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
                  </button>
                )}
                <div className="flex-1"><ListAgentCard node={node} depth={depth} /></div>
              </div>
              {isOpen && nodeChildren.length > 0 && (
                <div className="mt-1.5 space-y-1.5">
                  {renderTree(node.id, depth + 1)}
                </div>
              )}
            </div>
          )
        })
    }

    return children.map(node => {
      const nodeChildren = data.nodes.filter(n => n.reportsTo === node.id)
      const isOpen = expanded.has(node.id)
      return (
        <div key={node.id} className="relative">
          {depth > 0 && (
            <div className="absolute left-[11px] top-0 bottom-0 w-[2px]" style={{ backgroundColor: `${node.phaseColor}20` }} />
          )}
          <div className="flex items-center gap-1">
            {nodeChildren.length > 0 && (
              <button
                onClick={() => onToggleExpand(node.id)}
                className="p-0.5 rounded hover:bg-surface-2 text-text-muted shrink-0"
              >
                {isOpen ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
              </button>
            )}
            <div className="flex-1"><ListAgentCard node={node} depth={depth} /></div>
          </div>
          {isOpen && nodeChildren.length > 0 && (
            <div className="mt-1.5 space-y-1.5">
              {renderTree(node.id, depth + 1)}
            </div>
          )}
        </div>
      )
    })
  }

  return <div className="space-y-2">{renderTree(null, 0)}</div>
}

// ── Main Page ────────────────────────────────────────────────────────────────

const VIEW_OPTIONS = [
  { id: 'tree' as const, label: 'Tree', icon: GitBranch },
  { id: 'pipeline' as const, label: 'Pipeline', icon: LayoutGrid },
  { id: 'list' as const, label: 'List', icon: List },
]

type ViewType = 'tree' | 'pipeline' | 'list'

export default function OrgChartPage() {
  const [data, setData] = useState<OrgChartData | null>(null)
  const [loading, setLoading] = useState(true)
  const [view, setView] = useState<ViewType>('tree')
  const [expanded, setExpanded] = useState<Set<string>>(new Set(['rex', 'arya']))
  const [search, setSearch] = useState('')
  const [selectedNode, setSelectedNode] = useState<string | null>(null)

  useEffect(() => {
    getOrgChart().then(setData).catch(() => {}).finally(() => setLoading(false))
  }, [])

  const toggleExpand = (id: string) => {
    setExpanded(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const selectedNodeData = useMemo(
    () => data?.nodes.find(n => n.id === selectedNode) ?? null,
    [data, selectedNode],
  )

  const handleNavigateToNode = useCallback((id: string) => {
    setSelectedNode(id)
  }, [])

  if (loading) return <div className="p-8 text-text-muted">Loading org chart...</div>
  if (!data) return <div className="p-8 text-red-400">Failed to load org chart</div>

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="px-8 pt-6 pb-4 space-y-4 shrink-0">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2.5">
              <Users className="w-6 h-6" /> Org Chart
            </h1>
            <p className="text-text-muted text-sm mt-1">
              {data.stats.totalAgents} agents &middot; {data.stats.byModel.opus || 0} Opus &middot; {data.stats.byModel.sonnet || 0} Sonnet
            </p>
          </div>

          {/* View toggle */}
          <div className="flex bg-surface-2 rounded-lg p-0.5">
            {VIEW_OPTIONS.map(opt => {
              const Icon = opt.icon
              return (
                <button
                  key={opt.id}
                  onClick={() => setView(opt.id)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                    view === opt.id
                      ? 'bg-accent text-white'
                      : 'text-text-muted hover:text-text'
                  }`}
                >
                  <Icon className="w-3.5 h-3.5" />
                  {opt.label}
                </button>
              )
            })}
          </div>
        </div>

        {/* Search */}
        <div className="flex items-center gap-3">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-muted" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search agents..."
              className="w-full pl-9 pr-3 py-2 text-sm bg-surface border border-border rounded-lg focus:border-accent outline-none"
            />
          </div>
          {view === 'list' && (
            <div className="flex gap-1">
              <button
                onClick={() => setExpanded(new Set(data.nodes.map(n => n.id)))}
                className="px-2.5 py-1.5 text-[11px] rounded-lg bg-surface-2 text-text-muted hover:text-text transition-colors"
              >
                Expand All
              </button>
              <button
                onClick={() => setExpanded(new Set())}
                className="px-2.5 py-1.5 text-[11px] rounded-lg bg-surface-2 text-text-muted hover:text-text transition-colors"
              >
                Collapse All
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 relative overflow-hidden">
        {/* Tree View */}
        {view === 'tree' && (
          <div className="h-full mx-8 mb-4 rounded-2xl border border-border overflow-hidden relative">
            <TreeView
              data={data}
              search={search}
              selectedNode={selectedNode}
              onSelectNode={setSelectedNode}
            />
            {/* Detail panel overlay */}
            {selectedNodeData && (
              <DetailPanel
                node={selectedNodeData}
                allNodes={data.nodes}
                onClose={() => setSelectedNode(null)}
                onNavigate={handleNavigateToNode}
              />
            )}
          </div>
        )}

        {/* Pipeline View */}
        {view === 'pipeline' && (
          <div className="px-8 pb-8 overflow-y-auto h-full">
            <PipelineView data={data} search={search} />
          </div>
        )}

        {/* List View */}
        {view === 'list' && (
          <div className="px-8 pb-8 overflow-y-auto h-full">
            <ListView
              data={data}
              search={search}
              expanded={expanded}
              onToggleExpand={toggleExpand}
            />
          </div>
        )}
      </div>

      {/* Stats footer */}
      {view !== 'tree' && (
        <div className="px-8 pb-6 shrink-0">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {Object.entries(data.stats.byTier).sort(([, a], [, b]) => b - a).map(([tier, count]) => {
              const TIcon = TIER_ICONS[tier] || Cpu
              return (
                <div key={tier} className="bg-surface rounded-xl border border-border p-3 flex items-center gap-3">
                  <TIcon className="w-4 h-4 text-text-muted" />
                  <div>
                    <div className="text-xs font-semibold capitalize">{tier}</div>
                    <div className="text-[10px] text-text-muted">{count} agents</div>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

