  const selectedNodeData = useMemo(
    () => data?.nodes.find(n => n.id === selectedNode) ?? null,
    [data, selectedNode],
  )

  const handleNavigateToNode = useCallback((id: string) => {
    setSelectedNode(id)
  }, [])

  if (loading) return <div className="p-8 text-text-muted">Loading org chart...</div>
  if (!data) return <div className="p-8 text-red-400">Failed to load org chart</div>

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="px-8 pt-6 pb-4 space-y-4 shrink-0">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2.5">
              <Users className="w-6 h-6" /> Org Chart
            </h1>
