@import "tailwindcss";

/* ─── Light mode (default) ───────────────────────────────────────────────── */
@theme {
  --color-bg: #f4f6f8;
  --color-surface: #ffffff;
  --color-surface-2: #eef1f5;
  --color-surface-3: #e0e5ec;
  --color-border: #c8d0db;
  --color-border-subtle: #dde2ea;

  /* Text — high contrast hierarchy */
  --color-text: #0d1117;
  --color-text-secondary: #3a4558;
  --color-text-muted: #5c6a82;

  /* Accent (indigo) — slightly deeper for light bg contrast */
  --color-accent: #4f46e5;
  --color-accent-hover: #4338ca;
  --color-accent-muted: rgba(79, 70, 229, 0.12);

  /* Status colors — deeper, readable on white */
  --color-green: #15803d;
  --color-green-muted: rgba(21, 128, 61, 0.1);
  --color-amber: #b45309;
  --color-amber-muted: rgba(180, 83, 9, 0.1);
  --color-red: #b91c1c;
  --color-red-muted: rgba(185, 28, 28, 0.1);
  --color-purple: #6d28d9;
  --color-purple-muted: rgba(109, 40, 217, 0.1);

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', 'Fira Code', monospace;
}

/* ─── Dark mode override ─────────────────────────────────────────────────── */
html[data-theme="dark"] {
  --color-bg: #09090b;
  --color-surface: #18181b;
  --color-surface-2: #27272a;
  --color-surface-3: #303033;
  --color-border: #3f3f46;
  --color-border-subtle: #27272a;
  --color-text: #fafafa;
  --color-text-secondary: #a1a1aa;
  --color-text-muted: #71717a;
  --color-accent: #6366f1;
  --color-accent-hover: #818cf8;
  --color-accent-muted: rgba(99, 102, 241, 0.15);
  --color-green: #22c55e;
  --color-green-muted: rgba(34, 197, 94, 0.15);
  --color-amber: #f59e0b;
  --color-amber-muted: rgba(245, 158, 11, 0.15);
  --color-red: #ef4444;
  --color-red-muted: rgba(239, 68, 68, 0.15);
  --color-purple: #a78bfa;
  --color-purple-muted: rgba(167, 139, 250, 0.15);
}

@layer base {
  body {
    @apply bg-bg text-text font-sans antialiased;
  }

  ::selection {
    @apply bg-accent/25;
  }

  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    @apply bg-transparent;
  }
  ::-webkit-scrollbar-thumb {
    @apply bg-border rounded-full;
  }
  ::-webkit-scrollbar-thumb:hover {
    @apply bg-text-muted;
  }
}

/* ─── Chat animations ────────────────────────────────────────────────────── */

/* Message fade-in (only for new messages appearing) */
@keyframes chat-fade-in {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

.chat-fade-in {
  animation: chat-fade-in 0.15s ease-out;
}

/* ─── Markdown in chat ───────────────────────────────────────────────────── */

.markdown-chat p:first-child {
  margin-top: 0;
}

.markdown-chat p:last-child {
  margin-bottom: 0;
}

.markdown-chat pre {
  margin: 0;
}

/* Syntax highlighter overrides for dark mode consistency */
.markdown-chat .code-block-wrapper {
  border-radius: 0.5rem;
  overflow: hidden;
}

.markdown-chat .code-block-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.375rem 0.75rem;
  background: var(--color-surface-2);
  border-bottom: 1px solid var(--color-border);
}

/* ─── Rich Editor (Tiptap) ──────────────────────────────────────────────── */

.rich-editor-content {
  padding: 1.25rem 1.5rem;
  min-height: 300px;
  font-size: 14px;
  line-height: 1.75;
  color: var(--color-text);
}

.rich-editor-content > *:first-child {
  margin-top: 0;
}

/* Headings */
.rich-editor-content h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 1.5rem 0 0.5rem;
  color: var(--color-text);
}
.rich-editor-content h2 {
  font-size: 1.25rem;
  font-weight: 600;
  margin: 1.25rem 0 0.5rem;
  color: var(--color-text);
}
.rich-editor-content h3 {
  font-size: 1.1rem;
  font-weight: 600;
  margin: 1rem 0 0.4rem;
  color: var(--color-text);
}
.rich-editor-content h4 {
