                </span>
              ))}
            </div>
          </div>
        )}

        {/* Reports to */}
        {reportsToNode && (
          <div>
            <p className="text-[11px] uppercase tracking-wider text-text-muted font-semibold mb-1.5">Reports to</p>
            <button
              onClick={() => onNavigate(reportsToNode.id)}
              className="flex items-center gap-2 px-3 py-2 rounded-lg bg-surface-2 hover:bg-surface-3 transition-colors w-full text-left"
            >
              <AgentIcon name={extractEmoji(reportsToNode.name).cleanName} uid={`rpt-${reportsToNode.id}`} size={24} global />
              <div>
                <span className="text-xs font-semibold">{extractEmoji(reportsToNode.name).cleanName}</span>
                <span className="text-[10px] text-text-muted block">{reportsToNode.title}</span>
              </div>
            </button>
          </div>
        )}

        {/* Direct reports */}
        {directReports.length > 0 && (
          <div>
            <p className="text-[11px] uppercase tracking-wider text-text-muted font-semibold mb-1.5">
              Direct reports ({directReports.length})
            </p>
            <div className="space-y-1.5">
              {directReports.map(r => {
                const { cleanName: rName } = extractEmoji(r.name)
                return (
                  <button
                    key={r.id}
                    onClick={() => onNavigate(r.id)}
                    className="flex items-center gap-2 px-3 py-2 rounded-lg bg-surface-2 hover:bg-surface-3 transition-colors w-full text-left"
                  >
                    <AgentIcon name={rName} uid={`dr-${r.id}`} size={24} global />
                    <div className="min-w-0">
                      <span className="text-xs font-semibold truncate block">{rName}</span>
                      <span className="text-[10px] text-text-muted">{r.title}</span>
                    </div>
                    <div
                      className="w-2 h-2 rounded-full ml-auto shrink-0"
                      style={{ backgroundColor: r.phaseColor }}
                    />
                  </button>
                )
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

// ── Tree View (ReactFlow) ────────────────────────────────────────────────────

function TreeViewInner({
  data,
  search,
  selectedNode,
  onSelectNode,
}: {
  data: OrgChartData
  search: string
  selectedNode: string | null
  onSelectNode: (id: string | null) => void
}) {
  const { rfNodes: initialNodes, rfEdges: initialEdges } = useMemo(
    () => computeTreeLayout(data.nodes),
    [data.nodes],
  )

  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes)
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges)
  const reactFlowInstance = useReactFlow()

  // Apply search dimming
  useEffect(() => {
    if (!search) {
      setNodes(nds =>
        nds.map(n => ({ ...n, data: { ...n.data, dimmed: false } })),
      )
      setEdges(eds =>
        eds.map(e => ({
          ...e,
          style: { ...e.style, opacity: 0.6 },
        })),
      )
      return
    }

    const q = search.toLowerCase()
    const matchIds = new Set(
      data.nodes
        .filter(n =>
          n.name.toLowerCase().includes(q)
          || n.title.toLowerCase().includes(q)
          || n.id.toLowerCase().includes(q)
          || (n.description || '').toLowerCase().includes(q),
        )
        .map(n => n.id),
    )

    // Include ancestors of matches
    const relevantIds = new Set<string>()
    const addAncestors = (id: string) => {
      relevantIds.add(id)
      const node = data.nodes.find(n => n.id === id)
      if (node?.reportsTo) addAncestors(node.reportsTo)
    }
    matchIds.forEach(id => addAncestors(id))

    setNodes(nds =>
      nds.map(n => ({
        ...n,
        data: { ...n.data, dimmed: !relevantIds.has(n.id) },
      })),
    )
    setEdges(eds =>
      eds.map(e => ({
        ...e,
        style: {
          ...e.style,
          opacity: relevantIds.has(e.source) && relevantIds.has(e.target) ? 0.6 : 0.08,
        },
      })),
    )

    // Fit view to matching nodes
    const matchingNodes = nodes.filter(n => matchIds.has(n.id))
    if (matchingNodes.length > 0) {
      setTimeout(() => {
        reactFlowInstance.fitView({
          nodes: matchingNodes,
          padding: 0.4,
          duration: 400,
        })
      }, 50)
    }
  }, [search, data.nodes, setNodes, setEdges, reactFlowInstance, nodes])

  const handleNodeClick = useCallback(
    (_: React.MouseEvent, node: Node<OrgAgentNodeData>) => {
      onSelectNode(node.id === selectedNode ? null : node.id)
    },
    [onSelectNode, selectedNode],
  )

  const handlePaneClick = useCallback(() => {
    onSelectNode(null)
  }, [onSelectNode])

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      onEdgesChange={onEdgesChange}
      onNodeClick={handleNodeClick}
      onPaneClick={handlePaneClick}
      nodeTypes={nodeTypes}
      nodesDraggable={false}
      nodesConnectable={false}
      elementsSelectable
      fitView
      fitViewOptions={{ padding: 0.3 }}
      minZoom={0.2}
      maxZoom={1.5}
      proOptions={{ hideAttribution: true }}
      className="bg-bg"
    >
      <Background variant={BackgroundVariant.Dots} gap={20} size={1} className="!bg-bg" />
      <Controls
        showInteractive={false}
        className="!bg-surface !border-border !rounded-xl !shadow-lg [&>button]:!bg-surface [&>button]:!border-border [&>button]:!text-text-muted [&>button:hover]:!bg-surface-2"
      />
      <MiniMap
        nodeColor={(n) => {
          const nodeData = n.data as OrgAgentNodeData
          return nodeData.phaseColor || '#6b7280'
        }}
        maskColor="rgba(0,0,0,0.2)"
        className="!bg-surface !border-border !rounded-xl"
        pannable
        zoomable
      />
    </ReactFlow>
  )
}

function TreeView(props: {
  data: OrgChartData
  search: string
  selectedNode: string | null
  onSelectNode: (id: string | null) => void
}) {
  return (
    <ReactFlowProvider>
      <TreeViewInner {...props} />
    </ReactFlowProvider>
  )
}

