interface OrgAgentNodeData {
  agentId: string
  name: string
  emoji: string
  title: string
  model: string
  tier: string
  phaseColor: string
  phaseLabel: string | null
  description: string
  tools: string
  reportsTo: string | null
  childCount: number
  dimmed: boolean
  [key: string]: unknown
}

