  if (!cron.validate(cronExpr)) return res.status(400).json({ error: 'Invalid cron expression' });

  const schedule = {
    id: genId(),
    name,
    agentName,
    prompt,
    cron: cronExpr,
    enabled: enabled !== false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    lastRunAt: null,
    lastRunStatus: null,
  };
  const schedules = loadSchedules();
  schedules.push(schedule);
  saveSchedules(schedules);
  if (schedule.enabled) startScheduleJob(schedule);
  res.json(schedule);
});

app.put('/api/schedules/:id', rateLimit('write'), (req, res) => {
  const schedules = loadSchedules();
  const idx = schedules.findIndex(s => s.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Schedule not found' });

  const { name, agentName, prompt, cronExpr, enabled } = req.body;
  if (cronExpr && !cron.validate(cronExpr)) return res.status(400).json({ error: 'Invalid cron expression' });

  if (name !== undefined) schedules[idx].name = name;
  if (agentName !== undefined) schedules[idx].agentName = agentName;
  if (prompt !== undefined) schedules[idx].prompt = prompt;
  if (cronExpr !== undefined) schedules[idx].cron = cronExpr;
  if (enabled !== undefined) schedules[idx].enabled = enabled;
  schedules[idx].updatedAt = new Date().toISOString();
  saveSchedules(schedules);

  // Restart/stop cron job
  if (schedules[idx].enabled) startScheduleJob(schedules[idx]);
  else if (activeJobs.has(schedules[idx].id)) { activeJobs.get(schedules[idx].id).stop(); activeJobs.delete(schedules[idx].id); }

  res.json(schedules[idx]);
});

app.delete('/api/schedules/:id', rateLimit('write'), (req, res) => {
  if (activeJobs.has(req.params.id)) { activeJobs.get(req.params.id).stop(); activeJobs.delete(req.params.id); }
  saveSchedules(loadSchedules().filter(s => s.id !== req.params.id));
  res.json({ ok: true });
});

// ── Webhooks — external trigger endpoints ───────────────────────────────────

app.get('/api/webhooks', rateLimit('read'), (req, res) => {
  const webhooks = loadWebhooks().map(w => ({ ...w, secret: '****' + w.secret.slice(-8) }));
  res.json(webhooks);
});

app.get('/api/webhooks/:id/secret', rateLimit('read'), (req, res) => {
  const webhook = loadWebhooks().find(w => w.id === req.params.id);
  if (!webhook) return res.status(404).json({ error: 'Webhook not found' });
  res.json({ secret: webhook.secret });
});

app.post('/api/webhooks', rateLimit('write'), (req, res) => {
  const { name, agentName, orchestrationId } = req.body;
  if (!name || (!agentName && !orchestrationId)) return res.status(400).json({ error: 'name and either agentName or orchestrationId required' });

  const webhook = {
    id: 'wh_' + genId(),
    name,
    agentName: agentName || null,
    orchestrationId: orchestrationId || null,
    secret: crypto.randomBytes(32).toString('hex'),
    createdAt: new Date().toISOString(),
    lastTriggeredAt: null,
    triggerCount: 0,
  };
  const webhooks = loadWebhooks();
  webhooks.push(webhook);
  saveWebhooks(webhooks);
  res.json(webhook);
});

app.delete('/api/webhooks/:id', rateLimit('write'), (req, res) => {
  saveWebhooks(loadWebhooks().filter(w => w.id !== req.params.id));
  res.json({ ok: true });
});

app.post('/api/webhooks/trigger/:id', rateLimit('heavy'), async (req, res) => {
  const webhooks = loadWebhooks();
  const webhook = webhooks.find(w => w.id === req.params.id);
  if (!webhook) return res.status(404).json({ error: 'Webhook not found' });

  const secret = req.headers['x-webhook-secret'];
  if (!secret || secret !== webhook.secret) return res.status(401).json({ error: 'Invalid webhook secret' });

  // Update trigger stats
  webhook.lastTriggeredAt = new Date().toISOString();
  webhook.triggerCount = (webhook.triggerCount || 0) + 1;
  saveWebhooks(webhooks);

  const payload = JSON.stringify(req.body || {}, null, 2);
  const startTime = Date.now();

  try {
    if (webhook.agentName) {
      const prompt = buildScheduledPrompt({ agentName: webhook.agentName, prompt: `Webhook triggered: ${webhook.name}\n\nPayload:\n${payload}` });
      const output = await runClaudeSync(prompt, 300000);
      logAgentRun({ agentName: webhook.agentName, prompt: `Webhook: ${webhook.name}`, output, source: 'webhook', duration: Date.now() - startTime, status: 'success', metadata: { webhookId: webhook.id } });
      res.json({ success: true, output: output.slice(0, 500) });
    } else if (webhook.orchestrationId) {
      // Load and run orchestration
      const orc = loadOrchestrations().find(o => o.id === webhook.orchestrationId);
      if (!orc) return res.status(404).json({ error: 'Orchestration not found' });
      // Run synchronously (not SSE for webhooks)
      const orcResults = {};
      let orcLastOutput = payload;
      const orcOrder = topoSort(orc.nodes, orc.edges || []);
      const orcNodeMap = Object.fromEntries(orc.nodes.map(n => [n.id, n]));
      const agentContentMap = {};
      const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
      for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;

      for (const nid of orcOrder) {
        const nd = orcNodeMap[nid];
        if (!nd) continue;
        if (nd.data?.isStart) { orcResults[nid] = `Webhook: ${webhook.name}\n\n${payload}`; continue; }
        const aName = nd.data?.agentName;
        const baseInst = aName ? (agentContentMap[aName] || '') : '';
        const nodeInst = nd.data?.instructions || '';
        const incoming = (orc.edges || []).filter(e => e.target === nid);
        let ctx = incoming.length > 0
          ? incoming.map(e => `## Output from ${orcNodeMap[e.source]?.data?.label || e.source}:\n${orcResults[e.source] || ''}`).join('\n\n')
          : `## Task:\n${payload}`;
        let p = '';
        if (baseInst) p += baseInst + '\n\n';
        if (nodeInst) p += `## Your Specific Task:\n${nodeInst}\n\n`;
        p += `---\n\n${ctx}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly.`;
        const nStart = Date.now();
        try {
          const out = await runClaudeSync(p);
          orcResults[nid] = out;
          orcLastOutput = out;
          logAgentRun({ agentName: aName || 'custom', prompt: p.slice(0, 500), output: out, source: 'webhook', duration: Date.now() - nStart, status: 'success', metadata: { webhookId: webhook.id, orchestrationId: webhook.orchestrationId, nodeId: nid } });
        } catch (err) {
          logAgentRun({ agentName: aName || 'custom', prompt: p.slice(0, 500), output: '', source: 'webhook', duration: Date.now() - nStart, status: 'error', error: err.message, metadata: { webhookId: webhook.id } });
          return res.json({ success: false, error: err.message });
        }
      }
      res.json({ success: true, output: orcLastOutput.slice(0, 500) });
    } else {
      res.status(400).json({ error: 'Webhook has no agent or orchestration configured' });
    }
  } catch (err) {
    logAgentRun({ agentName: webhook.agentName || 'webhook', prompt: `Webhook: ${webhook.name}`, output: '', source: 'webhook', duration: Date.now() - startTime, status: 'error', error: err.message, metadata: { webhookId: webhook.id } });
    res.status(500).json({ success: false, error: err.message });
  }
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

// ══════════════════════════════════════════════════════════════════════════════
// ── Agent Performance Learning System (ruflo-inspired SONA pattern) ──────────
// Tracks per-agent per-task-type success rates, latency, token efficiency.
// Agents get smarter over time — routing improves based on historical data.
// ══════════════════════════════════════════════════════════════════════════════

function loadAgentLearning() {
  try { if (fs.existsSync(AGENT_LEARNING_PATH)) return JSON.parse(fs.readFileSync(AGENT_LEARNING_PATH, 'utf-8')); } catch {}
  return { agents: {}, taskTypes: {}, routing: {}, updatedAt: null };
}
function saveAgentLearning(data) {
  data.updatedAt = new Date().toISOString();
  fs.writeFileSync(AGENT_LEARNING_PATH, JSON.stringify(data, null, 2));
}

// Record a learning event (called after every agent run)
function recordLearning(agentName, taskType, outcome) {
  const db = loadAgentLearning();

  // Initialize agent profile if missing
  if (!db.agents[agentName]) {
    db.agents[agentName] = {
      totalRuns: 0, successRuns: 0, failedRuns: 0,
      avgDuration: 0, avgTokens: 0, avgCost: 0,
      taskTypes: {}, // per-task-type stats
      streak: 0, bestStreak: 0,
      firstSeen: new Date().toISOString(),
      lastSeen: null,
    };
  }
  const agent = db.agents[agentName];
  agent.totalRuns++;
  agent.lastSeen = new Date().toISOString();

  if (outcome.success) {
    agent.successRuns++;
    agent.streak = Math.max(0, agent.streak) + 1;
    agent.bestStreak = Math.max(agent.bestStreak, agent.streak);
  } else {
    agent.failedRuns++;
    agent.streak = 0;
  }

  // Rolling averages (exponential moving average, alpha=0.1)
  const alpha = 0.1;
  agent.avgDuration = agent.avgDuration === 0 ? (outcome.duration || 0) :
    agent.avgDuration * (1 - alpha) + (outcome.duration || 0) * alpha;
  agent.avgTokens = agent.avgTokens === 0 ? (outcome.tokens || 0) :
    agent.avgTokens * (1 - alpha) + (outcome.tokens || 0) * alpha;
  agent.avgCost = agent.avgCost === 0 ? (outcome.cost || 0) :
    agent.avgCost * (1 - alpha) + (outcome.cost || 0) * alpha;

  // Per task-type stats
  const tt = taskType || 'general';
  if (!agent.taskTypes[tt]) {
    agent.taskTypes[tt] = { runs: 0, successes: 0, avgDuration: 0 };
  }
  const tts = agent.taskTypes[tt];
  tts.runs++;
  if (outcome.success) tts.successes++;
  tts.avgDuration = tts.avgDuration * (1 - alpha) + (outcome.duration || 0) * alpha;

  // Global task-type stats
  if (!db.taskTypes[tt]) {
    db.taskTypes[tt] = { bestAgent: null, bestRate: 0, agents: {} };
  }
  db.taskTypes[tt].agents[agentName] = {
    successRate: Math.round((tts.successes / tts.runs) * 100),
    avgDuration: Math.round(tts.avgDuration),
    runs: tts.runs,
  };

  // Update best agent for this task type
  let bestAgent = null, bestRate = 0;
  for (const [name, stats] of Object.entries(db.taskTypes[tt].agents)) {
    if (stats.runs >= 3 && stats.successRate > bestRate) {
      bestRate = stats.successRate;
      bestAgent = name;
    }
  }
  db.taskTypes[tt].bestAgent = bestAgent;
  db.taskTypes[tt].bestRate = bestRate;

  saveAgentLearning(db);
  return { agent: agentName, taskType: tt, successRate: Math.round((agent.successRuns / agent.totalRuns) * 100) };
}

// API: Get learning data
app.get('/api/learning', rateLimit('read'), (req, res) => {
  res.json(loadAgentLearning());
});

// API: Get optimal agent for a task type
app.get('/api/learning/route/:taskType', rateLimit('read'), (req, res) => {
  const db = loadAgentLearning();
  const tt = req.params.taskType;
  const taskData = db.taskTypes[tt];
  if (!taskData || !taskData.bestAgent) {
    return res.json({ taskType: tt, recommendation: null, message: 'Not enough data yet' });
  }
  res.json({
    taskType: tt,
    recommendation: taskData.bestAgent,
    successRate: taskData.bestRate,
    alternatives: Object.entries(taskData.agents)
      .sort((a, b) => b[1].successRate - a[1].successRate)
      .map(([name, stats]) => ({ name, ...stats })),
  });
});

// API: Get agent performance profile
app.get('/api/learning/agent/:name', rateLimit('read'), (req, res) => {
  const db = loadAgentLearning();
  const agent = db.agents[req.params.name];
  if (!agent) return res.status(404).json({ error: 'Agent not found in learning data' });
  res.json({ name: req.params.name, ...agent, successRate: Math.round((agent.successRuns / agent.totalRuns) * 100) });
});

// API: Record a learning event manually
app.post('/api/learning/record', rateLimit('write'), (req, res) => {
  const { agentName, taskType, success, duration, tokens, cost, feedback } = req.body;
  if (!agentName) return res.status(400).json({ error: 'agentName required' });
  const result = recordLearning(agentName, taskType, { success: !!success, duration, tokens, cost, feedback });
  res.json(result);
});

// API: Reset learning data for an agent
app.delete('/api/learning/agent/:name', rateLimit('write'), (req, res) => {
  const db = loadAgentLearning();
  delete db.agents[req.params.name];
  // Clean from task types
  for (const tt of Object.values(db.taskTypes)) {
    delete tt.agents[req.params.name];
  }
  saveAgentLearning(db);
  res.json({ ok: true });
});

// ══════════════════════════════════════════════════════════════════════════════
// ── Claims System (ruflo-inspired, prevent duplicate agent work) ─────────────
// Agents claim tasks before starting. Others see it claimed and skip.
// Supports timeout (stale claims auto-release) and handoff.
// ══════════════════════════════════════════════════════════════════════════════

function loadClaims() {
  try { if (fs.existsSync(CLAIMS_PATH)) return JSON.parse(fs.readFileSync(CLAIMS_PATH, 'utf-8')); } catch {} return {};
}
function saveClaims(data) {
  fs.writeFileSync(CLAIMS_PATH, JSON.stringify(data, null, 2));
}

// Cleanup stale claims (>30 min old) every 5 minutes
setInterval(() => {
  try {
    const claims = loadClaims();
    const cutoff = Date.now() - 30 * 60 * 1000; // 30 min timeout
    let cleaned = 0;
    for (const [taskId, claim] of Object.entries(claims)) {
      if (new Date(claim.claimedAt).getTime() < cutoff && claim.status === 'active') {
        claim.status = 'expired';
        cleaned++;
      }
    }
    if (cleaned > 0) saveClaims(claims);
  } catch {}
}, 5 * 60 * 1000);

// API: Claim a task
app.post('/api/claims', rateLimit('write'), (req, res) => {
  const { taskId, agentName, description } = req.body;
  if (!taskId || !agentName) return res.status(400).json({ error: 'taskId and agentName required' });

  const claims = loadClaims();
  const existing = claims[taskId];

  // Check if already claimed by active agent
  if (existing && existing.status === 'active') {
    const age = Date.now() - new Date(existing.claimedAt).getTime();
    if (age < 30 * 60 * 1000) { // Still valid (< 30 min)
      return res.status(409).json({
        error: 'Task already claimed',
        claimedBy: existing.agentName,
        claimedAt: existing.claimedAt,
        age: Math.round(age / 1000) + 's',
      });
    }
  }

  claims[taskId] = {
    agentName,
    description: description || '',
    status: 'active',
    claimedAt: new Date().toISOString(),
    completedAt: null,
    result: null,
  };
  saveClaims(claims);
  res.json({ ok: true, taskId, claimedBy: agentName });
});

// API: Release/complete a claim
app.put('/api/claims/:taskId', rateLimit('write'), (req, res) => {
  const claims = loadClaims();
  const claim = claims[req.params.taskId];
  if (!claim) return res.status(404).json({ error: 'Claim not found' });

  const { status, result } = req.body; // status: 'completed' | 'released' | 'failed'
  claim.status = status || 'completed';
  claim.completedAt = new Date().toISOString();
  claim.result = result || null;
  saveClaims(claims);
  res.json({ ok: true, claim });
});

// API: Handoff a claim to another agent
app.post('/api/claims/:taskId/handoff', rateLimit('write'), (req, res) => {
  const claims = loadClaims();
  const claim = claims[req.params.taskId];
  if (!claim) return res.status(404).json({ error: 'Claim not found' });

  const { toAgent, reason } = req.body;
  if (!toAgent) return res.status(400).json({ error: 'toAgent required' });

  const previousAgent = claim.agentName;
  claim.agentName = toAgent;
  claim.claimedAt = new Date().toISOString();
  claim.handoffHistory = claim.handoffHistory || [];
  claim.handoffHistory.push({ from: previousAgent, to: toAgent, reason, at: new Date().toISOString() });
  saveClaims(claims);
  res.json({ ok: true, handoff: { from: previousAgent, to: toAgent } });
});

// API: List all claims
app.get('/api/claims', rateLimit('read'), (req, res) => {
  const claims = loadClaims();
  const { status, agent } = req.query;
  let entries = Object.entries(claims).map(([taskId, c]) => ({ taskId, ...c }));
  if (status) entries = entries.filter(c => c.status === status);
  if (agent) entries = entries.filter(c => c.agentName === agent);
  res.json(entries);
});

// API: Check if a task is claimed
app.get('/api/claims/:taskId', rateLimit('read'), (req, res) => {
  const claims = loadClaims();
  const claim = claims[req.params.taskId];
  if (!claim || claim.status !== 'active') {
    return res.json({ claimed: false });
  }
  res.json({ claimed: true, ...claim });
});

// ══════════════════════════════════════════════════════════════════════════════
// ── Cost-Based Model Routing (ruflo-inspired, 60-75% API savings) ────────────
// Route tasks to appropriate model tier based on complexity.
// Simple tasks → Haiku ($0.25/M), Medium → Sonnet ($3/M), Complex → Opus ($15/M)
// ══════════════════════════════════════════════════════════════════════════════

function loadModelRouting() {
  try { if (fs.existsSync(MODEL_ROUTING_PATH)) return JSON.parse(fs.readFileSync(MODEL_ROUTING_PATH, 'utf-8')); } catch {}
  return {
    rules: [
      { pattern: 'copy|tagline|headline|microcopy|CTA|subject line', model: 'haiku', tier: 'simple', agents: ['quill'] },
      { pattern: 'test|lint|format|rename|refactor simple', model: 'haiku', tier: 'simple', agents: ['luna'] },
      { pattern: 'build|implement|feature|component|page|API', model: 'sonnet', tier: 'medium', agents: ['koda'] },
      { pattern: 'review|audit|security|compliance', model: 'sonnet', tier: 'medium', agents: ['sage'] },
      { pattern: 'debug|fix|triage|root cause', model: 'sonnet', tier: 'medium', agents: ['vex'] },
      { pattern: 'architecture|system design|data model|migration', model: 'opus', tier: 'complex', agents: ['arya'] },
      { pattern: 'orchestrate|coordinate|full build|sprint', model: 'opus', tier: 'complex', agents: ['rex'] },
      { pattern: 'research|competitor|market|positioning', model: 'sonnet', tier: 'medium', agents: ['nova'] },
      { pattern: 'SEO|structured data|sitemap|core web vitals', model: 'sonnet', tier: 'medium', agents: ['zeph'] },
      { pattern: 'deploy|CI/CD|release|rollback', model: 'sonnet', tier: 'medium', agents: ['bolt'] },
      { pattern: 'monitor|alert|incident|sentry', model: 'haiku', tier: 'simple', agents: ['hawk'] },
      { pattern: 'knowledge|extract|lesson|train|memory', model: 'haiku', tier: 'simple', agents: ['mira'] },
      { pattern: 'design|visual|UI|UX|layout|component spec', model: 'sonnet', tier: 'medium', agents: ['vega'] },
    ],
    costs: {
      haiku: { input: 0.25, output: 1.25, label: 'Fast & cheap' },
      sonnet: { input: 3, output: 15, label: 'Balanced' },
      opus: { input: 15, output: 75, label: 'Deep reasoning' },
    },
    updatedAt: new Date().toISOString(),
  };
}
function saveModelRouting(data) {
  data.updatedAt = new Date().toISOString();
  fs.writeFileSync(MODEL_ROUTING_PATH, JSON.stringify(data, null, 2));
}

// API: Get recommended model for a task
app.post('/api/routing/recommend', rateLimit('read'), (req, res) => {
  const { agentName, taskDescription } = req.body;
  const routing = loadModelRouting();

  // Check agent-specific rules first
  for (const rule of routing.rules) {
    if (rule.agents && rule.agents.includes(agentName)) {
      return res.json({
        model: rule.model,
        tier: rule.tier,
        reason: `Agent ${agentName} defaults to ${rule.model}`,
        cost: routing.costs[rule.model],
      });
    }
  }

  // Check task description patterns
  if (taskDescription) {
    const desc = taskDescription.toLowerCase();
    for (const rule of routing.rules) {
      const patterns = rule.pattern.split('|');
      if (patterns.some(p => desc.includes(p.trim().toLowerCase()))) {
        return res.json({
          model: rule.model,
          tier: rule.tier,
          reason: `Task matched pattern: ${rule.pattern}`,
          cost: routing.costs[rule.model],
        });
      }
    }
  }

  // Default to sonnet
  res.json({
    model: 'sonnet',
    tier: 'medium',
    reason: 'Default (no specific rule matched)',
    cost: routing.costs.sonnet,
  });
});

// API: Get/update routing rules
app.get('/api/routing', rateLimit('read'), (req, res) => {
  res.json(loadModelRouting());
});

app.put('/api/routing', rateLimit('write'), (req, res) => {
  const routing = loadModelRouting();
  if (req.body.rules) routing.rules = req.body.rules;
  if (req.body.costs) routing.costs = req.body.costs;
  saveModelRouting(routing);
  res.json({ ok: true });
});

// API: Estimate cost savings
app.get('/api/routing/savings', rateLimit('read'), (req, res) => {
  const runs = loadAgentRuns();
  const routing = loadModelRouting();

  let allOpusCost = 0, routedCost = 0;
  for (const run of runs) {
    const tokens = run.estimatedTokens || 0;
    const inputTokens = Math.ceil(tokens * 0.7); // ~70% input
    const outputTokens = tokens - inputTokens;

    // Cost if everything ran on Opus
    allOpusCost += (inputTokens * 15 + outputTokens * 75) / 1_000_000;

    // Cost with routing
    let model = 'sonnet'; // default
    for (const rule of routing.rules) {
      if (rule.agents && rule.agents.includes(run.agentName)) { model = rule.model; break; }
    }
    const costs = routing.costs[model] || routing.costs.sonnet;
    routedCost += (inputTokens * costs.input + outputTokens * costs.output) / 1_000_000;
  }

  res.json({
    totalRuns: runs.length,
    allOpusCost: Math.round(allOpusCost * 10000) / 10000,
    routedCost: Math.round(routedCost * 10000) / 10000,
    savings: Math.round((1 - routedCost / (allOpusCost || 1)) * 100),
    message: `Estimated ${Math.round((1 - routedCost / (allOpusCost || 1)) * 100)}% savings with model routing`,
  });
});

// ── Global error handler ──────────────────────────────────────────────────────
app.use((err, req, res, _next) => {
  console.error(`[ERROR] ${req.method} ${req.url}:`, err.message);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
  });
});

// ── Uncaught error safety net ─────────────────────────────────────────────────
process.on('uncaughtException', (err) => {
  console.error('[UNCAUGHT EXCEPTION]', err);
});
process.on('unhandledRejection', (reason) => {
  console.error('[UNHANDLED REJECTION]', reason);
});

const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
  console.log('');
  console.log('  ╔══════════════════════════════════════╗');
  console.log('  ║         Claude Hub is running         ║');
  console.log(`  ║     http://localhost:${PORT}            ║`);
  console.log('  ╚══════════════════════════════════════╝');
  console.log('');
  console.log(`  Claude dir: ${CLAUDE_DIR}`);
  console.log(`  Config: ${CONFIG_PATH}`);

  // Restore scheduled cron jobs
  try {
    const schedules = loadSchedules();
    let active = 0;
    for (const s of schedules) {
      if (s.enabled) { startScheduleJob(s); active++; }
    }
    if (active > 0) console.log(`  Schedules: ${active} active cron job(s) restored`);
  } catch {}

  console.log('');
});

