import { useState } from 'react'
import { Pencil, Trash2, Plus, Check, X, Settings2 } from 'lucide-react'

const CATEGORY_COLORS: Record<string, { bg: string; text: string; dot: string }> = {
  'software-factory': { bg: 'bg-purple-500/10', text: 'text-purple-400', dot: 'bg-purple-400' },
  personal: { bg: 'bg-blue-500/10', text: 'text-blue-400', dot: 'bg-blue-400' },
  research: { bg: 'bg-emerald-500/10', text: 'text-emerald-400', dot: 'bg-emerald-400' },
  'client-work': { bg: 'bg-orange-500/10', text: 'text-orange-400', dot: 'bg-orange-400' },
  automation: { bg: 'bg-cyan-500/10', text: 'text-cyan-400', dot: 'bg-cyan-400' },
  marketing: { bg: 'bg-pink-500/10', text: 'text-pink-400', dot: 'bg-pink-400' },
  devops: { bg: 'bg-red-500/10', text: 'text-red-400', dot: 'bg-red-400' },
  design: { bg: 'bg-indigo-500/10', text: 'text-indigo-400', dot: 'bg-indigo-400' },
  uncategorized: { bg: 'bg-zinc-500/10', text: 'text-zinc-400', dot: 'bg-zinc-400' },
}

const EXTRA_COLORS = [
  { bg: 'bg-teal-500/10', text: 'text-teal-400', dot: 'bg-teal-400' },
  { bg: 'bg-lime-500/10', text: 'text-lime-400', dot: 'bg-lime-400' },
  { bg: 'bg-violet-500/10', text: 'text-violet-400', dot: 'bg-violet-400' },
  { bg: 'bg-fuchsia-500/10', text: 'text-fuchsia-400', dot: 'bg-fuchsia-400' },
  { bg: 'bg-rose-500/10', text: 'text-rose-400', dot: 'bg-rose-400' },
]

export function getColors(category: string) {
  if (CATEGORY_COLORS[category]) return CATEGORY_COLORS[category]
  let hash = 0
  for (let i = 0; i < category.length; i++) hash = ((hash << 5) - hash + category.charCodeAt(i)) | 0
  return EXTRA_COLORS[Math.abs(hash) % EXTRA_COLORS.length]
}

export function formatCategory(cat: string): string {
  return cat.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase())
}

function slugifyCategory(name: string): string {
  return name.trim().toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '')
}

export function AgentCategoryBadge({ category }: { category?: string }) {
  const cat = category || 'uncategorized'
  const colors = getColors(cat)
  const label = formatCategory(cat)

  return (
    <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-medium ${colors.bg} ${colors.text}`}>
      <span className={`w-1.5 h-1.5 rounded-full ${colors.dot}`} />
      {label}
    </span>
  )
}

export function CategoryFilterPills({
  categories,
  selected,
  onSelect,
  onRename,
  onDelete,
  onCreate,
}: {
  categories: { name: string; count: number }[]
  selected: string
  onSelect: (cat: string) => void
  onRename?: (oldName: string, newName: string) => Promise<void>
  onDelete?: (category: string, reassignTo: string) => Promise<void>
  onCreate?: (name: string) => void
}) {
  const total = categories.reduce((sum, c) => sum + c.count, 0)
  const [managing, setManaging] = useState(false)
  const [editingCat, setEditingCat] = useState<string | null>(null)
  const [editValue, setEditValue] = useState('')
  const [deletingCat, setDeletingCat] = useState<string | null>(null)
  const [reassignTarget, setReassignTarget] = useState('uncategorized')
  const [creatingNew, setCreatingNew] = useState(false)
  const [newCatName, setNewCatName] = useState('')
  const [busy, setBusy] = useState(false)

  const hasManagement = onRename && onDelete

  const handleRename = async () => {
    if (!onRename || !editingCat || !editValue.trim()) return
    const slug = slugifyCategory(editValue)
    if (!slug || slug === editingCat) { setEditingCat(null); return }
    setBusy(true)
    try {
      await onRename(editingCat, slug)
      setEditingCat(null)
      setEditValue('')
    } finally { setBusy(false) }
  }

  const handleDelete = async () => {
    if (!onDelete || !deletingCat) return
    setBusy(true)
    try {
      await onDelete(deletingCat, reassignTarget)
      setDeletingCat(null)
      setReassignTarget('uncategorized')
    } finally { setBusy(false) }
  }

  const handleCreate = () => {
    if (!onCreate || !newCatName.trim()) return
    const slug = slugifyCategory(newCatName)
    if (!slug) return
    onCreate(slug)
    setNewCatName('')
    setCreatingNew(false)
  }

  return (
    <div className="space-y-2">
      {/* Filter pills row */}
      <div className="flex items-center gap-1 flex-wrap">
        <button
          onClick={() => onSelect('all')}
          className={`px-2.5 py-1 rounded-full text-[11px] font-medium transition-colors ${
            selected === 'all'
              ? 'bg-accent text-white'
              : 'text-text-secondary hover:text-text hover:bg-surface-2'
          }`}
        >
          All ({total})
        </button>
        {categories.map(cat => {
          const colors = getColors(cat.name)
          const label = formatCategory(cat.name)
          return (
            <button
              key={cat.name}
              onClick={() => onSelect(cat.name)}
              className={`px-2.5 py-1 rounded-full text-[11px] font-medium transition-colors ${
                selected === cat.name
                  ? `${colors.bg} ${colors.text}`
                  : 'text-text-secondary hover:text-text hover:bg-surface-2'
              }`}
            >
              {label} ({cat.count})
            </button>
          )
        })}

        {/* Manage button */}
        {hasManagement && (
          <button
            onClick={() => setManaging(!managing)}
            className={`p-1 rounded-full transition-colors ml-1 ${
              managing ? 'bg-accent/10 text-accent' : 'text-text-muted hover:text-text hover:bg-surface-2'
            }`}
            title="Manage categories"
          >
            <Settings2 className="w-3.5 h-3.5" />
          </button>
        )}
      </div>

      {/* Management panel */}
      {managing && hasManagement && (
        <div className="bg-surface-2/50 rounded-lg border border-border/50 p-3 space-y-2">
          <div className="flex items-center justify-between mb-1">
            <span className="text-[11px] font-semibold text-text-muted uppercase tracking-wider">Manage Categories</span>
            <div className="flex items-center gap-1">
              <button
                onClick={() => setCreatingNew(true)}
                className="flex items-center gap-1 px-2 py-0.5 text-[10px] font-medium rounded-md bg-accent/10 text-accent hover:bg-accent/20 transition-colors"
              >
                <Plus className="w-3 h-3" /> New
              </button>
              <button
                onClick={() => { setManaging(false); setEditingCat(null); setDeletingCat(null); setCreatingNew(false) }}
                className="p-0.5 rounded text-text-muted hover:text-text"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>

          {/* Create new category */}
          {creatingNew && (
            <div className="flex items-center gap-2 bg-surface rounded-lg px-2.5 py-2 border border-accent/20">
              <Plus className="w-3 h-3 text-accent shrink-0" />
              <input
                value={newCatName}
                onChange={e => setNewCatName(e.target.value)}
                placeholder="Category name..."
                className="flex-1 bg-transparent text-xs outline-none placeholder:text-text-muted"
                autoFocus
                onKeyDown={e => { if (e.key === 'Enter') handleCreate(); if (e.key === 'Escape') setCreatingNew(false) }}
              />
              <span className="text-[9px] text-text-muted font-mono">{slugifyCategory(newCatName) || 'slug'}</span>
              <button onClick={handleCreate} disabled={!newCatName.trim()} className="p-0.5 text-green hover:text-green/80 disabled:opacity-30">
                <Check className="w-3.5 h-3.5" />
              </button>
              <button onClick={() => { setCreatingNew(false); setNewCatName('') }} className="p-0.5 text-text-muted hover:text-text">
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
          )}

          {/* Category list */}
          {categories.map(cat => {
            const colors = getColors(cat.name)
            const label = formatCategory(cat.name)
            const isEditing = editingCat === cat.name
            const isDeleting = deletingCat === cat.name

            if (isEditing) {
              return (
                <div key={cat.name} className="flex items-center gap-2 bg-surface rounded-lg px-2.5 py-2 border border-accent/20">
                  <Pencil className="w-3 h-3 text-accent shrink-0" />
                  <input
                    value={editValue}
                    onChange={e => setEditValue(e.target.value)}
                    className="flex-1 bg-transparent text-xs outline-none"
                    autoFocus
                    onKeyDown={e => { if (e.key === 'Enter') handleRename(); if (e.key === 'Escape') setEditingCat(null) }}
                  />
                  <span className="text-[9px] text-text-muted font-mono">{slugifyCategory(editValue)}</span>
                  <button onClick={handleRename} disabled={busy} className="p-0.5 text-green hover:text-green/80 disabled:opacity-50">
                    <Check className="w-3.5 h-3.5" />
                  </button>
                  <button onClick={() => setEditingCat(null)} className="p-0.5 text-text-muted hover:text-text">
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              )
            }

            if (isDeleting) {
              return (
                <div key={cat.name} className="bg-surface rounded-lg px-2.5 py-2 border border-red/20 space-y-2">
                  <div className="flex items-center gap-2">
                    <Trash2 className="w-3 h-3 text-red shrink-0" />
                    <span className="text-xs">
                      Delete <strong className={colors.text}>{label}</strong>? Reassign {cat.count} agents to:
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <select
                      value={reassignTarget}
                      onChange={e => setReassignTarget(e.target.value)}
                      className="flex-1 bg-surface-2 border border-border rounded-md px-2 py-1 text-xs"
                    >
                      <option value="uncategorized">Uncategorized</option>
                      {categories.filter(c => c.name !== cat.name && c.name !== 'uncategorized').map(c => (
                        <option key={c.name} value={c.name}>{formatCategory(c.name)}</option>
                      ))}
                    </select>
                    <button
                      onClick={handleDelete}
                      disabled={busy}
                      className="px-2.5 py-1 text-[11px] font-medium bg-red/10 text-red rounded-md hover:bg-red/20 disabled:opacity-50"
                    >
                      {busy ? '...' : 'Delete'}
                    </button>
                    <button onClick={() => setDeletingCat(null)} className="p-0.5 text-text-muted hover:text-text">
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              )
            }

            return (
              <div key={cat.name} className="flex items-center gap-2 px-2.5 py-1.5 rounded-lg hover:bg-surface/50 group">
                <span className={`w-2 h-2 rounded-full ${colors.dot} shrink-0`} />
                <span className="text-xs font-medium flex-1">{label}</span>
                <span className="text-[10px] text-text-muted">{cat.count} agents</span>
                {cat.name !== 'uncategorized' && (
                  <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button
                      onClick={() => { setEditingCat(cat.name); setEditValue(cat.name.replace(/-/g, ' ')); setDeletingCat(null) }}
                      className="p-1 rounded text-text-muted hover:text-accent hover:bg-accent/10"
                      title="Rename"
                    >
                      <Pencil className="w-3 h-3" />
                    </button>
                    <button
                      onClick={() => { setDeletingCat(cat.name); setEditingCat(null) }}
                      className="p-1 rounded text-text-muted hover:text-red hover:bg-red/10"
                      title="Delete"
                    >
                      <Trash2 className="w-3 h-3" />
                    </button>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

