const GOALS_PATH = path.join(__dirname, '..', 'goals.json');

function loadGoals() {
  try { if (fs.existsSync(GOALS_PATH)) return JSON.parse(fs.readFileSync(GOALS_PATH, 'utf-8')); } catch {}
  return { mission: '', missionDescription: '', projectGoals: [], agentGoals: [] };
}
function saveGoals(data) {
  fs.writeFileSync(GOALS_PATH, JSON.stringify(data, null, 2));
}

app.get('/api/goals', rateLimit('read'), (req, res) => {
  res.json(loadGoals());
});

app.put('/api/goals/mission', rateLimit('write'), (req, res) => {
  const { mission, description } = req.body;
  if (!mission) return res.status(400).json({ error: 'mission is required' });
  const goals = loadGoals();
  goals.mission = mission;
  goals.missionDescription = description || '';
  goals.updatedAt = new Date().toISOString();
  saveGoals(goals);
  res.json(goals);
});

app.post('/api/goals/project', rateLimit('write'), (req, res) => {
  const { projectId, projectName, goal, description, priority } = req.body;
  if (!projectId || !goal) return res.status(400).json({ error: 'projectId and goal required' });
  const goals = loadGoals();
  const existing = goals.projectGoals.findIndex(g => g.projectId === projectId);
  const entry = {
    id: existing >= 0 ? goals.projectGoals[existing].id : genId(),
    projectId,
    projectName: projectName || projectId,
    goal,
    description: description || '',
    priority: priority || 'medium',
    status: 'active',
    createdAt: existing >= 0 ? goals.projectGoals[existing].createdAt : new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  if (existing >= 0) goals.projectGoals[existing] = entry;
  else goals.projectGoals.push(entry);
  saveGoals(goals);
  res.json(entry);
});

app.delete('/api/goals/project/:id', rateLimit('write'), (req, res) => {
  const goals = loadGoals();
  goals.projectGoals = goals.projectGoals.filter(g => g.id !== req.params.id);
  // Also remove agent goals linked to this project
  goals.agentGoals = goals.agentGoals.filter(g => g.projectGoalId !== req.params.id);
  saveGoals(goals);
  res.json({ ok: true });
});

app.post('/api/goals/agent', rateLimit('write'), (req, res) => {
  const { agentName, projectGoalId, goal, description, status } = req.body;
  if (!agentName || !goal) return res.status(400).json({ error: 'agentName and goal required' });
  const goals = loadGoals();
  const existing = goals.agentGoals.findIndex(g => g.agentName === agentName && g.projectGoalId === (projectGoalId || null));
  const entry = {
    id: existing >= 0 ? goals.agentGoals[existing].id : genId(),
    agentName,
    projectGoalId: projectGoalId || null,
    goal,
    description: description || '',
    status: status || 'active',
    createdAt: existing >= 0 ? goals.agentGoals[existing].createdAt : new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  if (existing >= 0) goals.agentGoals[existing] = entry;
  else goals.agentGoals.push(entry);
  saveGoals(goals);
  res.json(entry);
});

app.put('/api/goals/agent/:id', rateLimit('write'), (req, res) => {
  const goals = loadGoals();
  const idx = goals.agentGoals.findIndex(g => g.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Agent goal not found' });
  const { goal, description, status } = req.body;
  if (goal !== undefined) goals.agentGoals[idx].goal = goal;
  if (description !== undefined) goals.agentGoals[idx].description = description;
  if (status !== undefined) goals.agentGoals[idx].status = status;
  goals.agentGoals[idx].updatedAt = new Date().toISOString();
  saveGoals(goals);
  res.json(goals.agentGoals[idx]);
});

app.delete('/api/goals/agent/:id', rateLimit('write'), (req, res) => {
  const goals = loadGoals();
  goals.agentGoals = goals.agentGoals.filter(g => g.id !== req.params.id);
  saveGoals(goals);
  res.json({ ok: true });
});

// ── Analytics — agent run tracking & summaries ──────────────────────────────

app.get('/api/analytics/runs', rateLimit('read'), (req, res) => {
  let runs = loadAgentRuns();
  const { agent, status, source, from, to, limit, offset } = req.query;
  if (agent) runs = runs.filter(r => r.agentName === agent);
  if (status) runs = runs.filter(r => r.status === status);
  if (source) runs = runs.filter(r => r.source === source);
  if (from) runs = runs.filter(r => r.timestamp >= from);
  if (to) runs = runs.filter(r => r.timestamp <= to);
  const total = runs.length;
  const off = parseInt(offset) || 0;
  const lim = Math.min(parseInt(limit) || 50, 200);
  res.json({ total, runs: runs.slice(off, off + lim) });
});

app.get('/api/analytics/summary', rateLimit('read'), (req, res) => {
  const runs = loadAgentRuns();
  const summary = {};
  for (const run of runs) {
    if (!summary[run.agentName]) {
      summary[run.agentName] = { runCount: 0, totalDuration: 0, successCount: 0, totalEstimatedCost: 0, totalTokens: 0 };
    }
    const s = summary[run.agentName];
    s.runCount++;
    s.totalDuration += run.duration || 0;
    if (run.status === 'success') s.successCount++;
    s.totalEstimatedCost += run.estimatedCost || 0;
    s.totalTokens += run.estimatedTokens || 0;
  }
  // Compute averages
  const result = {};
  for (const [name, s] of Object.entries(summary)) {
    result[name] = {
      runCount: s.runCount,
      avgDuration: Math.round(s.totalDuration / s.runCount),
      successRate: Math.round((s.successCount / s.runCount) * 100),
      totalEstimatedCost: Math.round(s.totalEstimatedCost * 10000) / 10000,
      totalTokens: s.totalTokens,
    };
  }
  res.json(result);
});

// ── Schedules — cron-based agent runs ───────────────────────────────────────
const activeJobs = new Map();

function buildScheduledPrompt(schedule) {
  // Load agent instructions same as playground
  let instructions = '';
  const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
  if (fs.existsSync(globalAgentsDir)) {
    for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
      const fname = file.replace('.md', '');
      if (fname === schedule.agentName || fname.toLowerCase() === schedule.agentName.toLowerCase()) {
        instructions = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
        break;
      }
    }
  }
  if (instructions) {
    return `${instructions}\n\n---\n\n## Task:\n${schedule.prompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
  }
  return schedule.prompt;
}

function startScheduleJob(schedule) {
  if (activeJobs.has(schedule.id)) { activeJobs.get(schedule.id).stop(); activeJobs.delete(schedule.id); }
  if (!schedule.enabled || !cron.validate(schedule.cron)) return;

  const job = cron.schedule(schedule.cron, async () => {
    const startTime = Date.now();
    try {
      const prompt = buildScheduledPrompt(schedule);
      const output = await runClaudeSync(prompt, 300000);
      logAgentRun({ agentName: schedule.agentName, prompt: schedule.prompt, output, source: 'schedule', duration: Date.now() - startTime, status: 'success', metadata: { scheduleId: schedule.id } });
      const schedules = loadSchedules();
      const idx = schedules.findIndex(s => s.id === schedule.id);
      if (idx >= 0) { schedules[idx].lastRunAt = new Date().toISOString(); schedules[idx].lastRunStatus = 'success'; saveSchedules(schedules); }
    } catch (err) {
      logAgentRun({ agentName: schedule.agentName, prompt: schedule.prompt, output: '', source: 'schedule', duration: Date.now() - startTime, status: 'error', error: err.message, metadata: { scheduleId: schedule.id } });
      const schedules = loadSchedules();
      const idx = schedules.findIndex(s => s.id === schedule.id);
      if (idx >= 0) { schedules[idx].lastRunAt = new Date().toISOString(); schedules[idx].lastRunStatus = 'error'; saveSchedules(schedules); }
    }
  });
  activeJobs.set(schedule.id, job);
}

app.get('/api/schedules', rateLimit('read'), (req, res) => {
  res.json(loadSchedules());
});

app.post('/api/schedules', rateLimit('write'), (req, res) => {
  const { name, agentName, prompt, cronExpr, enabled } = req.body;
  if (!name || !agentName || !prompt || !cronExpr) return res.status(400).json({ error: 'name, agentName, prompt, cronExpr required' });
  if (!cron.validate(cronExpr)) return res.status(400).json({ error: 'Invalid cron expression' });

  const schedule = {
    id: genId(),
    name,
    agentName,
    prompt,
    cron: cronExpr,
    enabled: enabled !== false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    lastRunAt: null,
    lastRunStatus: null,
  };
  const schedules = loadSchedules();
  schedules.push(schedule);
  saveSchedules(schedules);
  if (schedule.enabled) startScheduleJob(schedule);
  res.json(schedule);
});

app.put('/api/schedules/:id', rateLimit('write'), (req, res) => {
  const schedules = loadSchedules();
  const idx = schedules.findIndex(s => s.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Schedule not found' });

  const { name, agentName, prompt, cronExpr, enabled } = req.body;
  if (cronExpr && !cron.validate(cronExpr)) return res.status(400).json({ error: 'Invalid cron expression' });

  if (name !== undefined) schedules[idx].name = name;
  if (agentName !== undefined) schedules[idx].agentName = agentName;
  if (prompt !== undefined) schedules[idx].prompt = prompt;
  if (cronExpr !== undefined) schedules[idx].cron = cronExpr;
  if (enabled !== undefined) schedules[idx].enabled = enabled;
  schedules[idx].updatedAt = new Date().toISOString();
  saveSchedules(schedules);

  // Restart/stop cron job
  if (schedules[idx].enabled) startScheduleJob(schedules[idx]);
  else if (activeJobs.has(schedules[idx].id)) { activeJobs.get(schedules[idx].id).stop(); activeJobs.delete(schedules[idx].id); }

  res.json(schedules[idx]);
});

app.delete('/api/schedules/:id', rateLimit('write'), (req, res) => {
  if (activeJobs.has(req.params.id)) { activeJobs.get(req.params.id).stop(); activeJobs.delete(req.params.id); }
  saveSchedules(loadSchedules().filter(s => s.id !== req.params.id));
  res.json({ ok: true });
});

