// Apply search dimming — leader nodes dim by id, department nodes dim per-member
useEffect(() => {
  const { matchIds } = computeSearchSets(data.nodes, search)

  setNodes(nds =>
    nds.map(n => {
      if (n.type === 'orgLeader') {
        const leaderData = n.data as LeaderNodeData
        return {
          ...n,
          data: {
            ...leaderData,
            dimmed: matchIds ? !matchIds.has(leaderData.id) : false,
          },
        }
      }
      if (n.type === 'orgDept') {
        const deptData = n.data as DepartmentNodeData
        const updatedMembers = deptData.members.map(m => ({
          ...m,
          dimmed: matchIds ? !matchIds.has(m.id) : false,
        }))
        const anyMatch = matchIds
          ? updatedMembers.some(m => !m.dimmed)
          : true
        return {
          ...n,
          data: {
            ...deptData,
            members: updatedMembers,
            dimmed: !anyMatch,
          },
        }
      }
      return n
    }),
  )

  // Dim edges whose target department has no matches
  setEdges(eds =>
    eds.map(e => {
      if (!matchIds) return { ...e, style: { ...e.style, opacity: 0.55 } }
      // Find the target department's members
      const targetDept = e.target.startsWith('dept-') ? e.target.slice(5) : null
      if (!targetDept) return e
      const deptMembers = data.nodes.filter(n => n.phase === targetDept)
      const hasMatch = deptMembers.some(m => matchIds.has(m.id))
      return {
        ...e,
        style: {
          ...e.style,
          opacity: hasMatch ? 0.55 : 0.08,
        },
      }
    }),
  )
}, [search, data.nodes, setNodes, setEdges])

