import { useState, useEffect, useCallback, useMemo } from 'react'
import {
  CloudUpload,
  Github,
  Check,
  X,
  AlertTriangle,
  RefreshCw,
  Download,
  History,
  Archive,
  Link as LinkIcon,
  Unplug,
  Eye,
  Clock,
  FileText,
  Loader,
  ChevronRight,
  Info,
} from 'lucide-react'
import {
  getBackupStatus,
  connectBackup,
  disconnectBackup,
  runBackupNow,
  listBackupCommits,
  previewBackupRestore,
  applyBackupRestore,
  listBackupSnapshots,
  restoreBackupSnapshot,
  type BackupStatus,
  type BackupCommit,
  type BackupDiffFile,
  type BackupSnapshot,
} from '../lib/api'
import { useApi } from '../hooks/useApi'
import { toast } from '../components/Toast'

type Tab = 'overview' | 'cloud' | 'snapshots'

function formatRelativeTime(iso: string | null): string {
  if (!iso) return 'never'
  const then = new Date(iso).getTime()
  const now = Date.now()
  const sec = Math.floor((now - then) / 1000)
  if (sec < 5) return 'just now'
  if (sec < 60) return `${sec}s ago`
  const min = Math.floor(sec / 60)
  if (min < 60) return `${min}m ago`
  const hr = Math.floor(min / 60)
  if (hr < 24) return `${hr}h ago`
  const day = Math.floor(hr / 24)
  return `${day}d ago`
}

function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`
  return `${(n / 1024 / 1024).toFixed(1)} MB`
}

export default function BackupPage() {
  const { data: status, refetch: refetchStatus, loading } = useApi(getBackupStatus)
  const [tab, setTab] = useState<Tab>('overview')

  // Auto-refresh status every 10 seconds
  useEffect(() => {
    const t = setInterval(refetchStatus, 10000)
    return () => clearInterval(t)
  }, [refetchStatus])

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 text-text-muted">
        <Loader className="w-5 h-5 animate-spin mr-2" />
        Loading backup status...
      </div>
    )
  }

  if (!status) {
    return (
      <div className="p-8 text-red-400">Failed to load backup status</div>
    )
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="px-8 pt-5 pb-4 shrink-0">
        <div className="flex items-center justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-3">
            <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-accent/20 to-purple/20 ring-1 ring-accent/20 flex items-center justify-center">
              <CloudUpload className="w-5 h-5 text-accent" />
            </div>
            <div>
              <h1 className="text-xl font-bold leading-tight">Backup</h1>
              <p className="text-[11px] text-text-muted">
                Protect your agents, memory, and config against data loss
              </p>
            </div>
          </div>

          <HealthChip status={status} />
        </div>

        {/* Tab bar */}
        <div className="flex items-center gap-1 mt-5 bg-surface-2 p-0.5 rounded-lg w-fit">
          <TabButton active={tab === 'overview'} onClick={() => setTab('overview')}>
            <CloudUpload className="w-3.5 h-3.5" /> Overview
          </TabButton>
          <TabButton active={tab === 'cloud'} onClick={() => setTab('cloud')}>
            <History className="w-3.5 h-3.5" /> Cloud History
          </TabButton>
          <TabButton active={tab === 'snapshots'} onClick={() => setTab('snapshots')}>
            <Archive className="w-3.5 h-3.5" /> Local Snapshots
          </TabButton>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto px-8 pb-8">
        {tab === 'overview' && <OverviewTab status={status} onRefresh={refetchStatus} />}
        {tab === 'cloud' && <CloudHistoryTab status={status} onRefresh={refetchStatus} />}
        {tab === 'snapshots' && <SnapshotsTab onRefresh={refetchStatus} />}
      </div>
    </div>
  )
}

// ── Health chip ──────────────────────────────────────────────────────────────

function HealthChip({ status }: { status: BackupStatus }) {
  if (!status.configured) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-500/10 text-amber-400 text-xs font-semibold">
        <AlertTriangle className="w-3.5 h-3.5" />
        Not Configured
      </span>
    )
  }
  if (!status.enabled) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-zinc-500/10 text-zinc-400 text-xs font-semibold">
        <Unplug className="w-3.5 h-3.5" />
        Paused
      </span>
    )
  }
  if (status.pendingQueue > 0) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-500/10 text-amber-400 text-xs font-semibold">
        <RefreshCw className="w-3.5 h-3.5" />
        {status.pendingQueue} Queued
      </span>
    )
  }
  if (status.lastBackupStatus === 'error') {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-red-500/10 text-red-400 text-xs font-semibold">
        <X className="w-3.5 h-3.5" />
        Error
      </span>
    )
  }
  return (
    <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-emerald-500/10 text-emerald-400 text-xs font-semibold">
      <Check className="w-3.5 h-3.5" />
      Protected
    </span>
  )
}

function TabButton({ active, onClick, children }: {
  active: boolean
  onClick: () => void
  children: React.ReactNode
}) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-md transition-colors ${
        active ? 'bg-accent text-white shadow-sm shadow-accent/25' : 'text-text-muted hover:text-text'
      }`}
    >
      {children}
    </button>
  )
}

// ── Overview Tab ─────────────────────────────────────────────────────────────

function OverviewTab({ status, onRefresh }: { status: BackupStatus; onRefresh: () => void }) {
  const [connecting, setConnecting] = useState(false)
  const [running, setRunning] = useState(false)
  const [repoUrl, setRepoUrl] = useState('')
  const [token, setToken] = useState('')
  const [showConnectForm, setShowConnectForm] = useState(!status.configured)

  const handleConnect = async () => {
    if (!repoUrl.trim() || !token.trim()) {
      toast('error', 'Repo URL and token are required')
      return
    }
    setConnecting(true)
    try {
      const res = await connectBackup(repoUrl.trim(), token.trim())
      if (!res.ok) {
        toast('error', res.error || 'Connection failed')
        return
      }
      toast('success', 'Backup connected successfully')
      setRepoUrl('')
      setToken('')
      setShowConnectForm(false)
      onRefresh()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Connection failed')
    } finally {
      setConnecting(false)
    }
  }

  const handleDisconnect = async () => {
    if (!confirm('Pause auto-backup? Your data stays backed up, but new changes won\'t be pushed until you reconnect.')) return
    try {
      await disconnectBackup()
      toast('success', 'Backup paused')
      onRefresh()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to disconnect')
    }
  }

  const handleBackupNow = async () => {
    setRunning(true)
    try {
      const res = await runBackupNow()
      if (!res.ok) {
        toast('error', res.error || 'Backup failed')
        return
      }
      if (res.committed) {
        toast('success', res.pushed ? 'Backup pushed to GitHub' : 'Committed locally (push queued)')
      } else {
        toast('success', 'No changes to back up')
      }
      onRefresh()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Backup failed')
    } finally {
      setRunning(false)
    }
  }

  return (
    <div className="space-y-4 max-w-4xl">
      {/* Connect flow */}
      {showConnectForm && (
        <div className="bg-surface rounded-2xl border border-border overflow-hidden">
          <div className="px-5 py-3 border-b border-border bg-gradient-to-r from-accent/5 to-transparent">
            <div className="flex items-center gap-2.5">
              <Github className="w-4 h-4 text-accent" />
              <h3 className="text-sm font-bold">Connect GitHub Repository</h3>
            </div>
          </div>
          <div className="px-5 py-5 space-y-4">
            <div className="bg-accent/5 border border-accent/20 rounded-lg px-4 py-3 text-xs text-text-secondary space-y-2">
              <div className="flex items-start gap-2">
                <Info className="w-3.5 h-3.5 text-accent shrink-0 mt-0.5" />
                <div className="flex-1 space-y-1.5">
                  <p className="font-semibold text-text">Setup steps:</p>
                  <ol className="list-decimal list-inside space-y-0.5 text-[11px]">
                    <li>Go to <a href="https://github.com/new" target="_blank" rel="noopener noreferrer" className="text-accent underline">github.com/new</a> → create a <strong>private</strong> repo (e.g. <code className="text-[10px] bg-surface-2 px-1 rounded">claude-hub-backup</code>)</li>
                    <li>Copy the HTTPS clone URL</li>
                    <li>Go to <a href="https://github.com/settings/tokens?type=beta" target="_blank" rel="noopener noreferrer" className="text-accent underline">Settings → Developer → Tokens</a> → create a fine-grained PAT with <strong>Repo: Read + Write</strong> access</li>
                    <li>Paste both below</li>
                  </ol>
                </div>
              </div>
            </div>

            <div>
              <label className="text-[11px] font-semibold text-text-muted uppercase tracking-wider block mb-1.5">
                Repository URL
              </label>
              <input
                value={repoUrl}
                onChange={(e) => setRepoUrl(e.target.value)}
                placeholder="https://github.com/yash/claude-hub-backup.git"
                className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/10"
              />
            </div>

            <div>
              <label className="text-[11px] font-semibold text-text-muted uppercase tracking-wider block mb-1.5">
                Personal Access Token
              </label>
              <input
                type="password"
                value={token}
                onChange={(e) => setToken(e.target.value)}
                placeholder="ghp_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
                className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/10 font-mono"
              />
              <p className="text-[10px] text-text-muted mt-1.5">
                Token is encrypted with a machine-local key before storage. It never leaves your machine in plain text.
              </p>
            </div>

            <div className="flex items-center gap-2 pt-1">
              <button
                onClick={handleConnect}
                disabled={connecting || !repoUrl.trim() || !token.trim()}
                className="flex items-center gap-2 px-4 py-2 text-sm font-semibold bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 transition-colors"
              >
                {connecting ? (
                  <>
                    <Loader className="w-4 h-4 animate-spin" />
                    Connecting & testing...
                  </>
                ) : (
                  <>
                    <LinkIcon className="w-4 h-4" />
                    Connect & Backup Now
                  </>
                )}
              </button>
              {status.configured && (
                <button
                  onClick={() => setShowConnectForm(false)}
                  className="px-4 py-2 text-sm font-medium text-text-muted hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
                >
                  Cancel
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Status cards */}
      {status.configured && !showConnectForm && (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <StatCard
              icon={Github}
              label="Repository"
              value={(
                <a
                  href={status.repoUrl?.replace(/\.git$/, '') || '#'}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-accent hover:underline break-all text-[12px] font-mono"
                >
                  {status.repoUrl?.replace(/^https?:\/\/(.*@)?/, '').replace(/\.git$/, '')}
                </a>
              )}
            />
            <StatCard
              icon={Clock}
              label="Last Backup"
              value={formatRelativeTime(status.lastBackupAt)}
              sublabel={status.lastBackupStatus || undefined}
            />
            <StatCard
              icon={Check}
              label="Total Commits"
              value={String(status.commitCount)}
              sublabel={status.lastCommitSha ? `${status.lastCommitSha.slice(0, 7)}` : undefined}
            />
            <StatCard
              icon={Archive}
              label="Local Snapshots"
              value={`${status.snapshotCount} / ${status.maxSnapshots}`}
              sublabel="auto-rotate oldest"
            />
          </div>

          {/* Error banner */}
          {status.lastBackupError && (
            <div className="bg-red-500/5 border border-red-500/20 rounded-xl px-4 py-3 flex items-start gap-3">
              <AlertTriangle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
              <div className="flex-1 min-w-0">
                <p className="text-xs font-semibold text-red-400">Last backup failed</p>
                <p className="text-[11px] text-text-muted mt-0.5 font-mono break-all">
                  {status.lastBackupError}
                </p>
              </div>
            </div>
          )}

          {/* Push queue warning */}
          {status.pendingQueue > 0 && (
            <div className="bg-amber-500/5 border border-amber-500/20 rounded-xl px-4 py-3 flex items-start gap-3">
              <RefreshCw className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-xs font-semibold text-amber-400">
                  {status.pendingQueue} commit{status.pendingQueue > 1 ? 's' : ''} waiting to push
                </p>
                <p className="text-[11px] text-text-muted mt-0.5">
                  Your data is committed locally and will push on the next successful backup.
                  {status.lastFailedPush && ` Last push error: ${status.lastFailedPush.error}`}
                </p>
              </div>
            </div>
          )}

          {/* Actions */}
          <div className="flex items-center gap-2 flex-wrap">
            <button
              onClick={handleBackupNow}
              disabled={running}
              className="flex items-center gap-2 px-4 py-2 text-sm font-semibold bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 transition-colors"
            >
              {running ? (
                <>
                  <Loader className="w-4 h-4 animate-spin" /> Backing up...
                </>
              ) : (
                <>
                  <CloudUpload className="w-4 h-4" /> Backup Now
                </>
              )}
            </button>
            <button
              onClick={onRefresh}
              className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-text-muted hover:text-text rounded-lg bg-surface-2 hover:bg-surface-3 transition-colors"
            >
              <RefreshCw className="w-3.5 h-3.5" /> Refresh
            </button>
            <button
              onClick={() => setShowConnectForm(true)}
              className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-text-muted hover:text-text rounded-lg bg-surface-2 hover:bg-surface-3 transition-colors"
            >
              <LinkIcon className="w-3.5 h-3.5" /> Change Repo
            </button>
            {status.enabled && (
              <button
                onClick={handleDisconnect}
                className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-red-400 hover:bg-red-500/10 rounded-lg transition-colors ml-auto"
              >
                <Unplug className="w-3.5 h-3.5" /> Pause Auto-Backup
              </button>
            )}
          </div>

          {/* What's included */}
          <div className="bg-surface rounded-2xl border border-border overflow-hidden">
            <div className="px-5 py-3 border-b border-border">
              <h3 className="text-sm font-bold">What's Backed Up</h3>
            </div>
            <div className="px-5 py-4 grid grid-cols-2 md:grid-cols-4 gap-2">
              {status.includePaths.map((p) => (
                <div
                  key={p}
                  className="flex items-center gap-2 px-2.5 py-1.5 rounded-lg bg-surface-2/60 text-[11px] font-mono"
                >
                  <Check className="w-3 h-3 text-emerald-400 shrink-0" />
                  {p}
                </div>
              ))}
            </div>
            <div className="px-5 pb-4 pt-1 text-[10px] text-text-muted">
              Auto-commits on every file save (5-sec debounce) · 15-minute safety-net commit · Failed pushes queued locally
            </div>
          </div>
        </>
      )}
    </div>
  )
}

function StatCard({
  icon: Icon,
  label,
  value,
  sublabel,
}: {
  icon: typeof Github
  label: string
  value: React.ReactNode
  sublabel?: string
}) {
  return (
    <div className="bg-surface rounded-xl border border-border p-4">
      <div className="flex items-center gap-2 mb-2">
        <Icon className="w-3.5 h-3.5 text-text-muted" />
        <span className="text-[10px] uppercase tracking-wider text-text-muted font-semibold">{label}</span>
      </div>
      <div className="text-sm font-bold break-words">{value}</div>
      {sublabel && (
        <div className="text-[10px] text-text-muted mt-0.5 font-mono">{sublabel}</div>
      )}
    </div>
  )
}

// ── Cloud History Tab ────────────────────────────────────────────────────────

function CloudHistoryTab({ status, onRefresh }: { status: BackupStatus; onRefresh: () => void }) {
  const { data: commits, loading, refetch } = useApi(useCallback(() => listBackupCommits(100), []))
  const [previewSha, setPreviewSha] = useState<string | null>(null)
  const [previewData, setPreviewData] = useState<{ totalFiles: number; changes: BackupDiffFile[] } | null>(null)
  const [previewLoading, setPreviewLoading] = useState(false)
  const [applying, setApplying] = useState(false)

  const handlePreview = async (commitSha: string) => {
    setPreviewSha(commitSha)
    setPreviewData(null)
    setPreviewLoading(true)
    try {
      const res = await previewBackupRestore(commitSha)
      if (res.ok) {
        setPreviewData({ totalFiles: res.totalFiles, changes: res.changes })
      } else {
        toast('error', res.error || 'Preview failed')
      }
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Preview failed')
    } finally {
      setPreviewLoading(false)
    }
  }

  const handleApply = async () => {
    if (!previewSha) return
    if (!confirm(`Restore ~/.claude/ to commit ${previewSha.slice(0, 7)}? This will overwrite current files. A fresh backup will be created first.`)) return
    setApplying(true)
    try {
      // Create a safety backup first
      await runBackupNow()
      const res = await applyBackupRestore(previewSha)
      if (res.ok) {
        toast('success', `Restored to ${previewSha.slice(0, 7)}`)
        setPreviewSha(null)
        setPreviewData(null)
        onRefresh()
      } else {
        toast('error', res.error || 'Restore failed')
      }
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Restore failed')
    } finally {
      setApplying(false)
    }
  }

  if (!status.configured) {
    return (
      <div className="bg-surface rounded-2xl border border-border p-12 text-center">
        <CloudUpload className="w-10 h-10 text-text-muted mx-auto mb-3 opacity-50" />
        <p className="text-sm font-medium text-text-muted">Connect a GitHub repo first</p>
        <p className="text-xs text-text-muted mt-1">Go to the Overview tab to set up cloud backup.</p>
      </div>
    )
  }

  return (
    <div className="max-w-4xl space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-bold">Commit History</h2>
        <button
          onClick={() => { refetch(); onRefresh() }}
          className="flex items-center gap-1.5 px-2.5 py-1.5 text-[11px] font-medium text-text-muted hover:text-text bg-surface-2 rounded-lg hover:bg-surface-3 transition-colors"
        >
          <RefreshCw className="w-3 h-3" /> Refresh
        </button>
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-12 text-text-muted">
          <Loader className="w-4 h-4 animate-spin mr-2" /> Loading commits...
        </div>
      ) : !commits || commits.length === 0 ? (
        <div className="bg-surface rounded-2xl border border-border p-10 text-center text-text-muted">
          <History className="w-8 h-8 mx-auto mb-2 opacity-50" />
          <p className="text-sm">No commits yet</p>
          <p className="text-xs mt-1">Run a backup from the Overview tab to create the first one.</p>
        </div>
      ) : (
        <div className="bg-surface rounded-2xl border border-border overflow-hidden">
          <div className="divide-y divide-border/50">
            {commits.map((commit, idx) => (
              <CommitRow
                key={commit.hash}
                commit={commit}
                isLatest={idx === 0}
                onPreview={() => handlePreview(commit.hash)}
              />
            ))}
          </div>
        </div>
      )}

      {/* Restore preview modal */}
      {previewSha && (
        <RestorePreviewModal
          commitSha={previewSha}
          data={previewData}
          loading={previewLoading}
          applying={applying}
          onClose={() => { setPreviewSha(null); setPreviewData(null) }}
          onApply={handleApply}
        />
      )}
    </div>
  )
}

function CommitRow({ commit, isLatest, onPreview }: {
  commit: BackupCommit
  isLatest: boolean
  onPreview: () => void
}) {
  const relTime = useMemo(() => formatRelativeTime(commit.date), [commit.date])

  return (
    <div className="group flex items-center gap-3 px-5 py-3 hover:bg-surface-2/40 transition-colors">
      <div className="w-2 h-2 rounded-full shrink-0" style={{
        backgroundColor: isLatest ? 'var(--color-accent)' : 'var(--color-border)',
      }} />
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-xs font-semibold truncate">{commit.message}</span>
          {isLatest && (
            <span className="text-[9px] px-1.5 py-0.5 rounded-full bg-accent/10 text-accent font-bold shrink-0">LATEST</span>
          )}
        </div>
        <div className="flex items-center gap-2 mt-0.5 text-[10px] text-text-muted">
          <span className="font-mono">{commit.shortHash}</span>
          <span>·</span>
          <span>{relTime}</span>
        </div>
      </div>
      <button
        onClick={onPreview}
        className="flex items-center gap-1.5 px-2.5 py-1 text-[11px] font-semibold rounded-lg text-text-muted hover:text-accent hover:bg-accent/10 transition-colors opacity-0 group-hover:opacity-100"
      >
        <Eye className="w-3 h-3" />
        Preview Restore
      </button>
    </div>
  )
}

function RestorePreviewModal({
  commitSha,
  data,
  loading,
  applying,
  onClose,
  onApply,
}: {
  commitSha: string
  data: { totalFiles: number; changes: BackupDiffFile[] } | null
  loading: boolean
  applying: boolean
  onClose: () => void
  onApply: () => void
}) {
  return (
    <div
      className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"
      onClick={() => !applying && onClose()}
    >
      <div
        className="w-full max-w-2xl bg-surface rounded-2xl border border-border shadow-2xl overflow-hidden flex flex-col max-h-[85vh]"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="px-5 py-4 border-b border-border flex items-start justify-between gap-3">
          <div className="flex items-start gap-3">
            <div className="w-10 h-10 rounded-xl bg-accent/10 flex items-center justify-center shrink-0">
              <Download className="w-5 h-5 text-accent" />
            </div>
            <div className="min-w-0">
              <h3 className="text-base font-bold">Restore Preview</h3>
              <p className="text-xs text-text-muted font-mono mt-0.5">
                Commit {commitSha.slice(0, 7)}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            disabled={applying}
            className="p-1.5 rounded-lg hover:bg-surface-2 text-text-muted transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="flex items-center justify-center py-12 text-text-muted">
              <Loader className="w-4 h-4 animate-spin mr-2" /> Computing diff...
            </div>
          ) : !data ? (
            <div className="px-5 py-8 text-center text-text-muted text-sm">
              No preview data
            </div>
          ) : data.totalFiles === 0 ? (
            <div className="px-5 py-8 text-center">
              <Check className="w-8 h-8 text-emerald-400 mx-auto mb-2" />
              <p className="text-sm font-medium">No changes</p>
              <p className="text-xs text-text-muted mt-1">
                Your current files match this commit exactly.
              </p>
            </div>
          ) : (
            <div>
              <div className="px-5 py-3 bg-accent/5 border-b border-border">
                <p className="text-xs">
                  <span className="font-bold text-accent">{data.totalFiles}</span> file{data.totalFiles !== 1 ? 's' : ''} will change if you restore this commit.
                </p>
              </div>
              <div className="divide-y divide-border/50">
                {data.changes.map((file) => (
                  <div key={file.file} className="px-5 py-2 flex items-center gap-3 text-xs">
                    <FileText className="w-3.5 h-3.5 text-text-muted shrink-0" />
                    <span className="flex-1 truncate font-mono">{file.file}</span>
                    <div className="flex items-center gap-1.5 shrink-0">
                      {file.insertions > 0 && (
                        <span className="text-emerald-400 font-bold">+{file.insertions}</span>
                      )}
                      {file.deletions > 0 && (
                        <span className="text-red-400 font-bold">-{file.deletions}</span>
                      )}
                      {file.binary && (
                        <span className="text-amber-400 text-[10px]">binary</span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="px-5 py-4 border-t border-border bg-surface-2/30 flex items-center justify-end gap-2">
          <button
            onClick={onClose}
            disabled={applying}
            className="px-4 py-2 text-sm font-semibold rounded-lg text-text-secondary hover:text-text hover:bg-surface-2 transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={onApply}
            disabled={applying || !data || data.totalFiles === 0}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 transition-colors"
          >
            {applying ? (
              <>
                <Loader className="w-3.5 h-3.5 animate-spin" /> Restoring...
              </>
            ) : (
              <>
                <Download className="w-3.5 h-3.5" /> Apply Restore
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  )
}

// ── Snapshots Tab ────────────────────────────────────────────────────────────

function SnapshotsTab({ onRefresh }: { onRefresh: () => void }) {
  const { data: snapshots, loading, refetch } = useApi(listBackupSnapshots)
  const [restoring, setRestoring] = useState<string | null>(null)

  const handleRestore = async (name: string) => {
    if (!confirm(`Restore this snapshot? It will overwrite the current file.`)) return
    setRestoring(name)
    try {
      const res = await restoreBackupSnapshot(name)
      if (res.ok) {
        toast('success', `Restored: ${res.restoredTo}`)
        onRefresh()
      } else {
        toast('error', res.error || 'Restore failed')
      }
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Restore failed')
    } finally {
      setRestoring(null)
    }
  }

  return (
    <div className="max-w-4xl space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-sm font-bold">Local Snapshots</h2>
          <p className="text-[11px] text-text-muted mt-0.5">
            Pre-edit backups created before automated agents (Tutor, Hira, Forge) modify your files.
          </p>
        </div>
        <button
          onClick={refetch}
          className="flex items-center gap-1.5 px-2.5 py-1.5 text-[11px] font-medium text-text-muted hover:text-text bg-surface-2 rounded-lg hover:bg-surface-3 transition-colors"
        >
          <RefreshCw className="w-3 h-3" /> Refresh
        </button>
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-12 text-text-muted">
          <Loader className="w-4 h-4 animate-spin mr-2" /> Loading snapshots...
        </div>
      ) : !snapshots || snapshots.length === 0 ? (
        <div className="bg-surface rounded-2xl border border-border p-10 text-center text-text-muted">
          <Archive className="w-8 h-8 mx-auto mb-2 opacity-50" />
          <p className="text-sm">No snapshots yet</p>
          <p className="text-xs mt-1">
            Snapshots are created automatically when Tutor, Hira, or Forge edit files.
          </p>
        </div>
      ) : (
        <div className="bg-surface rounded-2xl border border-border overflow-hidden">
          <div className="divide-y divide-border/50">
            {snapshots.map((snap) => (
              <SnapshotRow
                key={snap.name}
                snap={snap}
                restoring={restoring === snap.name}
                onRestore={() => handleRestore(snap.name)}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

function SnapshotRow({ snap, restoring, onRestore }: {
  snap: BackupSnapshot
  restoring: boolean
  onRestore: () => void
}) {
  return (
    <div className="group flex items-center gap-3 px-5 py-2.5 hover:bg-surface-2/40 transition-colors">
      <div className="w-8 h-8 rounded-lg bg-accent/5 flex items-center justify-center shrink-0">
        <FileText className="w-3.5 h-3.5 text-text-muted" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-xs font-semibold truncate font-mono">{snap.relPath}</span>
          <span className="text-[9px] px-1.5 py-0.5 rounded bg-surface-2 text-text-muted shrink-0">
            {snap.agent}
          </span>
        </div>
        <div className="flex items-center gap-2 mt-0.5 text-[10px] text-text-muted">
          <span>{formatRelativeTime(snap.mtime)}</span>
          <span>·</span>
          <span>{formatBytes(snap.size)}</span>
        </div>
      </div>
      <button
        onClick={onRestore}
        disabled={restoring}
        className="flex items-center gap-1.5 px-2.5 py-1 text-[11px] font-semibold rounded-lg text-text-muted hover:text-accent hover:bg-accent/10 transition-colors opacity-0 group-hover:opacity-100 disabled:opacity-50"
      >
        {restoring ? (
          <Loader className="w-3 h-3 animate-spin" />
        ) : (
          <>
            <ChevronRight className="w-3 h-3" />
            Restore
          </>
        )}
      </button>
    </div>
  )
}

